UPDATE categories SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"text": "Tìm hiểu về Phụ kiện đồng bộ của hệ thống cấp gió tươi", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Để hệ thống cấp khí tươi và thông gió hoạt động ổn định, êm ái và đạt hiệu suất cao nhất, việc sử dụng các phụ kiện đồng bộ tiêu chuẩn là vô cùng quan trọng. Điện máy ELC cung cấp đầy đủ các loại phụ kiện chính hãng phục vụ lắp đặt hệ thống gió tươi ERV/HRV chuyên nghiệp.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các loại phụ kiện gió tươi phân phối tại ELC", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Miệng gió nghệ thuật và miệng gió chống mưa:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Cửa gió khuếch tán trong nhà thẩm mỹ và miệng chụp gió ngoài trời inox tích hợp lưới ngăn côn trùng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ống gió mềm kháng khuẩn và ống gió bảo ôn:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ống dẫn gió tiêu chuẩn giảm ồn tốt, chống bám bụi và ngăn chặn rò rỉ nhiệt lạnh.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bộ chia gió, van chỉnh gió (VCD) và giảm chấn:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Điều tiết lưu lượng gió tươi cấp vào từng phòng dễ dàng theo thiết kế.", "type": "text"}]}]}]}]}'::jsonb WHERE slug = 'phu-kien-dong-bo-cua-he-thong-cap-gio-tuoi';
UPDATE categories SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Công Tắc Thông Minh ACIS: Giải Pháp Nhà Thông Minh Bền Bỉ Cho Mọi Công Trình", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Công tắc thông minh ACIS là thiết bị điều khiển hệ thống chiếu sáng, rèm cửa và các thiết bị điện trong nhà thông qua công nghệ không dây Mesh độc quyền. Thay vì sử dụng sóng Wi-Fi dễ bị xung đột hay quá tải khi lắp nhiều thiết bị, công tắc ACIS vận hành dựa trên mạng lưới tự thiết lập (Mesh Network), đảm bảo độ ổn định tuyệt đối, phản hồi tức thì và đặc biệt là khả năng ", "type": "text"}, {"text": "nâng cấp từ nhà thường lên nhà thông minh mà không cần đục phá tường", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tại Sao Nên Chọn Công Tắc Thông Minh ACIS?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khác với các dòng công tắc Zigbee hay Wi-Fi trôi nổi trên thị trường, ACIS định vị là giải pháp Smarthome cao cấp với sự ổn định đặt lên hàng đầu.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc điểm", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công tắc thông minh ACIS", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công tắc Wi-Fi/Zigbee thường", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Độ ổn định", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cực cao (Công nghệ Mesh độc quyền)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phụ thuộc vào modem Wi-Fi", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thi công", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp vừa đế âm tường tiêu chuẩn (Sino, Panasonic)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Có thể cần thay đế âm, đi dây lại", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Hoạt động không Internet", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Vẫn điều khiển tại chỗ bình thường", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thường mất kết nối hoặc chậm", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Độ bền", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Linh kiện công nghiệp, bảo hành dài hạn", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Linh kiện phổ thông, dễ lỗi sau 1-2 năm", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Công Nghệ Cốt Lõi Tạo Nên Sự Khác Biệt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Để tối ưu cho các từ khóa \\"công nghệ smarthome\\" và giúp bài viết của mày lên top AI Overview, hãy tập trung vào các điểm bán hàng độc nhất (USP) này:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ Mesh Network tự phục hồi:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Mỗi công tắc ACIS vừa là điểm nhận, vừa là điểm phát tín hiệu. Nếu một công tắc có vấn đề, các công tắc còn lại sẽ tự động định tuyến để giữ hệ thống hoạt động thông suốt. Đây là lý do ACIS xuyên tường cực tốt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế \\"Retrofit\\" (Nâng cấp không đục phá):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đây là từ khóa \\"vàng\\" cho dân SEO smarthome. Người dùng Việt rất sợ đục tường. Công tắc ACIS được thiết kế tương thích hoàn hảo với kích thước đế âm tường hình chữ nhật hoặc hình vuông mà các thợ điện hay lắp sẵn. Việc lắp đặt chỉ đơn giản là tháo công tắc cũ, đấu dây và lắp công tắc ACIS vào.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cảm ứng điện dung siêu nhạy:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Không cần nhấn mạnh, chỉ cần chạm nhẹ. Mặt kính cường lực chống trầy xước, chịu được môi trường nóng ẩm tại Việt Nam mà không bị liệt cảm ứng.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'cong-tac-thong-minh';
UPDATE categories SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh: Hướng Dẫn Toàn Diện Từ Khái Niệm Đến Cách Chọn Mua", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy lạnh treo tường (hay điều hòa treo tường) là hệ thống làm mát gồm hai cụm biệt lập: ", "type": "text"}, {"text": "dàn lạnh", "type": "text", "marks": [{"type": "bold"}]}, {"text": " được lắp trên tường bên trong phòng để phân phối khí mát, và ", "type": "text"}, {"text": "dàn nóng", "type": "text", "marks": [{"type": "bold"}]}, {"text": " được đặt ngoài trời để xả nhiệt. Đây là dòng máy lạnh phổ biến nhất hiện nay nhờ chi phí hợp lý, dễ lắp đặt và phù hợp với nhiều không gian.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Thương Hiệu Máy Lạnh Hàng Đầu", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thương Hiệu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thế Mạnh Cốt Lõi", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công Nghệ Nổi Bật", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phân Khúc Giá", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Daikin", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Độ bền cao, làm lạnh dễ chịu, tiết kiệm điện vượt trội", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Luồng gió Coanda, Máy nén Swing, Phin lọc Enzyme Blue", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Panasonic", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lọc không khí đỉnh cao, thiết kế sang trọng", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ Nanoe-X (diệt khuẩn), Eco tích hợp A.I", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "LG", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ hiện đại, giá hợp lý, kết nối thông minh", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dual Inverter, Thanh lọc UVnano, Smart ThinQ (Wi-Fi)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tầm trung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Casper", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá rẻ, làm lạnh nhanh, chính sách bảo hành cực tốt", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Làm lạnh nhanh Turbo, Tự làm sạch iClean", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá rẻ", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Phân Loại Máy Lạnh Theo Công Suất (Btu/h)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Việc chọn đúng công suất theo diện tích phòng giúp máy bền hơn và tiết kiệm điện năng tối đa.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho phòng có diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ nhỏ, phòng làm việc cá nhân).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho phòng từ ", "type": "text"}, {"text": "15 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho phòng từ ", "type": "text"}, {"text": "20 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách, văn phòng nhỏ, phòng họp).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho phòng từ ", "type": "text"}, {"text": "30 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Không gian mở, quán cafe nhỏ).", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Inverter (Tiết kiệm điện) vs Non-Inverter (Máy cơ)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh Inverter:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng máy nén công nghệ biến tần, tự động điều chỉnh tốc độ quay để duy trì nhiệt độ ổn định. Tiết kiệm từ 30% đến 60% điện năng nếu bật liên tục trên 5 tiếng, máy chạy êm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh Non-Inverter:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Máy nén chỉ có 2 trạng thái Bật (chạy hết công suất) và Tắt. Giá thành rẻ hơn, chi phí sửa chữa thấp nhưng tốn điện hơn và nhiệt độ dao động lớn.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Máy lạnh 1 chiều vs Máy lạnh 2 chiều", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh 1 chiều (Cooling):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chỉ có chức năng làm mát. Phù hợp với khí hậu miền Nam Việt Nam quanh năm nắng nóng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh 2 chiều (Heat pump):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Có cả chức năng làm mát và sưởi ấm. Phù hợp với miền Bắc hoặc vùng núi cao có mùa đông lạnh.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tiêu Chí Chọn Mua Máy Lạnh Cho Người Tiêu Dùng", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Xác định diện tích và thể tích phòng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đo chính xác diện tích phòng. Nếu phòng có trần cao hoặc bị hướng nắng chiếu trực tiếp, hãy cộng thêm công suất (ví dụ phòng 14m2 nhưng hướng Tây thì nên chọn 1.5 HP thay vì 1 HP).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chọn loại máy theo nhu cầu khí hậu:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nếu ở TP.HCM thì chọn máy 1 chiều để tiết kiệm chi phí đầu tư. Nếu ở Hà Nội hoặc Đà Lạt, cân nhắc máy 2 chiều.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cân nhắc tần suất sử dụng (Inverter hay không):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nếu bật máy trên 6 tiếng/ngày (phòng ngủ, phòng làm việc tại nhà), bắt buộc phải chọn ", "type": "text"}, {"text": "Inverter", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Nếu chỉ bật 1-2 tiếng trước khi ngủ hoặc lắp cho phòng trọ cho thuê, máy cơ (Non-Inverter) sẽ thu hồi vốn nhanh hơn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lựa chọn thương hiệu và tính năng đi kèm:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chọn thương hiệu theo ngân sách. Chú ý các tính năng như: Lọc bụi mịn PM2.5, tự động làm sạch dàn lạnh, hoặc kết nối Wi-Fi nếu bạn là người thích nhà thông minh.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'may-lanh-treo-tuong';
UPDATE categories SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Tủ Đứng: Giải Pháp Làm Lạnh Siêu Tốc Cho Không Gian Lớn", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng (hay điều hòa cây) là dòng máy lạnh có thiết kế dạng tủ đặt sàn độc lập. Dàn lạnh của máy có hình dáng như một chiếc tủ thời trang, đặt trực tiếp trên sàn nhà, giúp thổi ra luồng gió mạnh mẽ và đi xa hơn rất nhiều so với các dòng máy khác. Đây là lựa chọn tối ưu cho những không gian rộng lớn, có lượng người ra vào đông và đòi hỏi tốc độ làm mát tức thì.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Thương Hiệu Máy Lạnh Tủ Đứng Hàng Đầu Hiện Nay", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thương Hiệu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ưu Điểm Nổi Bật", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tầm Xa Luồng Gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phân Khúc Giá", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Daikin", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Độ bền công nghiệp, hoạt động bền bỉ 24/7, có cả dòng thổi trực tiếp và nối ống gió", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Rất xa và mạnh mẽ", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Panasonic", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế dạng tủ sang trọng như một món nội thất cao cấp, tích hợp công nghệ lọc khí Nanoe-X", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gió thổi êm ái, dễ chịu", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "LG", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kiểu dáng slim (siêu mỏng) tinh tế, tiết kiệm diện tích, công nghệ Smart Inverter cực tiết kiệm điện", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thổi xa lên đến 20 mét", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tầm trung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Casper / Midea", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá thành rẻ, làm lạnh nhanh cực kỳ nhanh với chế độ Turbo, chi phí đầu tư ban đầu thấp", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mạnh mẽ, trực diện", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá rẻ", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Phân Loại Công Suất Máy Lạnh Tủ Đứng Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Do đặc thù lắp ở không gian mở hoặc nơi đông người, công suất của dòng tủ đứng thường bắt đầu từ 2.5 HP trở lên:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP) - 28.000 Btu/h (3 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho không gian từ ", "type": "text"}, {"text": "30 - 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách lớn, quán cafe nhỏ, văn phòng làm việc).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "36.000 Btu/h (4 HP) - 45.000 Btu/h (5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "45 - 65m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Showroom thời trang, cửa hàng tiện lợi, nhà hàng kinh doanh).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "50.000 Btu/h (5.5 HP) - 100.000 Btu/h (10 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dòng máy công nghiệp công suất siêu lớn, phù hợp cho diện tích ", "type": "text"}, {"text": "trên 70m2 đến vài trăm m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Nhà xưởng, hội trường lớn, trung tâm tổ chức tiệc cưới).", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Điểm Cộng Vượt Trội Khiến Khách Hàng Chọn Máy Lạnh Tủ Đứng", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tốc độ làm lạnh \\"vô địch\\":", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Do thiết kế cánh quạt lớn và block máy mạnh mẽ, máy lạnh tủ đứng tạo ra lưu lượng gió cực đại, làm mát toàn bộ căn phòng rộng chỉ trong vài phút sau khi bật.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt và bảo dưỡng dễ như ăn kẹo:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Không cần phải khoan đục trần thạch cao phức tạp như dòng âm trần, cũng không cần bắt ti treo cao. Máy chỉ cần đặt trên sàn, kết nối ống đồng ra ngoài là xong. Việc vệ sinh lưới lọc cũng cực kỳ nhanh chóng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tính cơ động cao:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khi cần thay đổi thiết kế phòng hoặc di dời văn phòng/cửa hàng sang địa điểm mới, việc tháo dỡ và vận chuyển máy tủ đứng đơn giản và ít tốn chi phí hơn rất nhiều.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tiêu Chí Chọn Mua Và Lưu Ý Kỹ Thuật Khi Sử Dụng", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chọn vị trí đặt máy hợp lý:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Gió từ máy tủ đứng thổi rất mạnh và trực diện. Tránh đặt máy ở góc khuất bị che chắn bởi tủ kệ, và không nên để miệng gió thổi thẳng vào vị trí ngồi làm việc hoặc bàn ăn của khách hàng để tránh gây buốt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Luôn tính dư công suất (Tải nhiệt):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Không gian lắp máy tủ đứng thường có nhiều người ra vào, cửa mở liên tục hoặc có nhiều thiết bị sinh nhiệt (bếp lẩu, máy tính). Bạn nên chọn công suất lớn hơn từ 10% - 20% so với diện tích tiêu chuẩn để máy không bị quá tải.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cân nhắc dòng Inverter nếu bật liên tục:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Các mô hình kinh doanh mở cửa từ sáng đến tối muộn nên chọn dòng Inverter để tiết kiệm tối đa hóa đơn tiền điện hằng tháng, dù giá máy ban đầu sẽ cao hơn dòng máy cơ (Non-Inverter).", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'may-lanh-tu-dung';
UPDATE categories SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Cấp Khí Tươi Lọc Không Khí Menred: Giải Pháp Cho Không Gian Sống Xanh", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy cấp khí tươi lọc không khí (hay hệ thống thông gió thu hồi nhiệt - ERV/HRV) là thiết bị cao cấp có chức năng hút không khí ô nhiễm, ngột ngạt từ bên trong phòng thải ra ngoài, đồng thời hút không khí giàu oxy từ ngoài trời, đi qua hệ thống lõi lọc tiêu chuẩn cao để khử khuẩn, lọc bụi mịn rồi mới cấp vào bên trong nhà.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trong đó, ", "type": "text"}, {"text": "Menred", "type": "text", "marks": [{"type": "bold"}]}, {"text": " là thương hiệu tiên phong đến từ Đức, nổi tiếng với các giải pháp cấp khí tươi thông minh, giúp ngôi nhà luôn tràn ngập oxy mà không cần mở cửa, ngăn ngừa tối đa tình trạng bí bách, thiếu oxy trong phòng kín.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Máy Cấp Khí Tươi Menred Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tùy vào thực tế công trình (nhà đang ở hay đang xây trô), Menred cung cấp 2 giải pháp cốt lõi phù hợp với từng nhu cầu:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Loại Máy", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Vị Trí Lắp Đặt", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ưu Điểm Nổi Bật", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đối Tượng Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy cấp khí tươi âm trần (Central ERV)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp giấu trên trần thạch cao, đi ống gió đến từng phòng", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công suất lớn, cấp gió đa điểm cho toàn bộ ngôi nhà, tính thẩm mỹ tuyệt đối", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự, Penthouse, Căn hộ đang thi công phần thô, Văn phòng", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy cấp khí tươi treo tường (Wall-mounted)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Treo trực tiếp trên tường (chỉ cần khoan 1-2 lỗ thông ra ngoài)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt nhanh chóng, không ảnh hưởng đến trần nhà, thiết kế compact nhỏ gọn", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ căn hộ chung cư, Nhà phố đã hoàn thiện xong xuôi", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Công Nghệ Cốt Lõi Trên Máy Cấp Lọc Khí Tươi Menred", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ Thu Hồi Nhiệt (Energy Recovery Ventilator - ERV)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Đây là tính năng ăn tiền nhất. Khi hút khí lạnh (từ máy lạnh trong phòng) ra ngoài và cấp khí nóng (từ ngoài trời) vào, hai dòng khí này sẽ đi qua một ", "type": "text"}, {"text": "bộ trao đổi nhiệt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tại đây, khí tươi từ ngoài trời sẽ được làm mát trước khi đi vào phòng, giúp máy lạnh không bị sốc nhiệt và ", "type": "text"}, {"text": "tiết kiệm đến 70-80% năng lượng", "type": "text", "marks": [{"type": "bold"}]}, {"text": " so với việc mở cửa thông gió thông thường.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Hệ thống lọc đa tầng (Multi-stage Filtration)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Không khí ngoài trời thường chứa nhiều khói bụi, khí thải. Máy Menred được trang bị các màng lọc hiệu suất cao: Màng lọc thô (giữ lại tóc, bụi lớn) -> Màng lọc Carbon hoạt tính (khử mùi ô nhiễm, khí độc) -> ", "type": "text"}, {"text": "Màng lọc HEPA H13", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (giữ lại 99.97% bụi mịn PM2.5, vi khuẩn, virus).", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tại Sao Mọi Nhà Hiện Đại Đều Cần Máy Cấp Khí Tươi?", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Giải quyết tận gốc vấn đề thừa CO2:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phòng bật máy lạnh đóng kín cửa sau vài tiếng sẽ bị tích tụ khí CO2 do con người thở ra. Đây là nguyên nhân khiến bạn ngủ dậy bị mệt mỏi, đau đầu, uể oải. Máy Menred bổ sung Oxy liên tục giúp giấc ngủ sâu và tỉnh táo hơn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lọc bụi mịn và ngăn bụi từ ngoài vào:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thay vì mở cửa sổ để đón gió nhưng lại rước thêm bụi mịn, máy cấp khí tươi giúp nhà luôn thông thoáng nhưng hoàn toàn sạch bụi.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bảo vệ hệ thống nội thất và chống ẩm mốc:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kiểm soát độ ẩm tốt, ngăn chặn sự phát triển của nấm mốc trong các góc khuất của ngôi nhà.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tiêu Chí Khảo Sát Và Lắp Đặt Hệ Thống Khí Tươi Menred", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tính toán lưu lượng khí (m3/h) theo số người:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tiêu chuẩn thông thường là khoảng 30m3/h khí tươi cho một người. Ví dụ phòng ngủ 2 vợ chồng cần máy có lưu lượng tối thiểu 60-100m3/h.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Phối hợp thi công từ giai đoạn thô (Đối với dòng âm trần):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Hệ thống ống gió cấp khí tươi thường đi song song với ống máy lạnh giấu trần. Cần lên sơ đồ tuyến ống sớm để tránh xung đột vị trí.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lựa chọn vị trí đặt máy hợp lý:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dù máy Menred vận hành rất êm, nhưng dàn máy trung tâm âm trần nên được đặt ở các khu vực như logia, nhà vệ sinh, hoặc hành lang để triệt tiêu hoàn toàn tiếng ồn nhỏ trong phòng ngủ.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'may-cap-khi-tuoi-loc-khong-khi';
UPDATE categories SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hệ Thống Lọc Nước Cao Cấp Menred: Công Nghệ Đức Cho Nguồn Nước Tinh Khiết", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống lọc nước Menred (bao gồm các dòng Weißwasser, Rhine, Alpsee) là giải pháp xử lý nước cao cấp chuẩn châu Âu, được thiết kế để lắp đặt gọn gàng dưới tủ bếp hoặc làm hệ thống lọc trung tâm cho toàn bộ ngôi nhà. Sử dụng các công nghệ màng lọc tiên tiến nhất hiện nay là RO (Reverse Osmosis) và UF (Ultrafiltration), Menred giúp loại bỏ hoàn toàn vi khuẩn, kim loại nặng, hóa chất độc hại, mang lại nguồn nước sạch an toàn tuyệt đối, có thể uống trực tiếp tại vòi mà không cần đun sôi.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Máy Lọc Nước Menred", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tên Sản Phẩm", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công Nghệ Lọc", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Cốt Lõi", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Vị Trí Lắp Đặt / Nhu Cầu", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Weißwasser RO WR100.CHL01", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "RO (Thẩm thấu ngược)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng máy cao cấp, công suất lớn, có màn hình hiển thị chỉ số tinh khiết (TDS), thiết kế thông minh gọn gàng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp dưới tủ bếp, dùng để lấy nước uống trực tiếp, nấu ăn cho gia đình.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Rhine (Rhine Series)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "RO (Thẩm thấu ngược)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lấy cảm hứng từ dòng sông Rhine, nhấn mạnh vào độ bền của lõi lọc, tỷ lệ thu hồi nước tinh khiết cao, tiết kiệm nước thải.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp âm tủ bếp căn hộ, nhà phố. Phù hợp cho nhu cầu sử dụng nước liên tục.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Alpsee Series", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "RO (Thẩm thấu ngược)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phân khúc siêu cao cấp, mô phỏng nguồn nước tinh khiết từ dãy Alps. Lọc sạch ở cấp độ phân tử, giữ vị nước ngọt tự nhiên.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp cho biệt thự, villa cao cấp, kết hợp với vòi nước thông minh.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Weißwasser UF WU2.SH01", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "UF (Siêu lọc / Ultrafiltration)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không dùng điện, không có nước thải. Loại bỏ vi khuẩn nhưng ", "type": "text"}, {"text": "giữ lại các khoáng chất tự nhiên", "type": "text", "marks": [{"type": "bold"}]}, {"text": " có sẵn trong nước.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dùng làm lọc chặn đầu nguồn cho bếp, hoặc cho người thích uống nước còn khoáng.", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tìm Hiểu Bản Chất Công Nghệ: RO và UF của Menred Khác Nhau Thế Nào?", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ Thẩm thấu ngược RO (Dòng Weißwasser RO, Rhine, Alpsee)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cơ chế:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng màng lọc có kích thước siêu nhỏ chỉ 0.0001 micron. Máy bắt buộc dùng điện và có phát sinh nước thải.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chất lượng nước:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Loại bỏ 99.99% tất cả những gì không phải là nước (kim loại nặng như chì, thủy ngân, asen, vi khuẩn, thuốc trừ sâu). Nước ra là nước ", "type": "text"}, {"text": "tinh khiết hoàn toàn", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", uống cực kỳ an toàn.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Công nghệ Siêu lọc UF (Dòng Weißwasser UF WU2.SH01)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cơ chế:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng màng sợi rỗng với kích thước lọc khoảng 0.01 - 0.1 micron. Hoạt động nhờ áp lực nước tự nhiên, ", "type": "text"}, {"text": "không cần dùng điện, không có nước thải", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chất lượng nước:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giữ lại được các ", "type": "text"}, {"text": "khoáng chất tự nhiên", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Canxi, Magie...) có lợi cho cơ thể. Phù hợp với những khu vực có nguồn nước máy đầu vào tương đối tốt.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Điểm Cộng Tối Ưu Tốc Độ Của Máy Lọc Nước Menred", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế Tankless (Không bình chứa):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Các dòng RO đời mới của Menred đa số thiết kế không cần bình chứa cồng kềnh. Nước được lọc trực tiếp với công suất lớn (Flow rate cao), giúp nước luôn tươi mới, không sợ bị tái nhiễm khuẩn ở bình chứa và tiết kiệm 70% không gian dưới tủ bếp.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống lõi lọc Quick-Change:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Người dùng có thể tự thay lõi tại nhà chỉ bằng một thao tác vặn nhẹ, không cần gọi thợ kỹ thuật, không sợ rò rỉ nước.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tích hợp chip thông minh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Cảnh báo thời gian thay lõi trực tiếp trên thân máy hoặc trên vòi nước điện tử, giúp kiểm soát chất lượng nước 24/7.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'may-loc-nuoc-ro-3-in-1';
UPDATE categories SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Bảng Điều Khiển ACIS: Đỉnh Cao Công Nghệ Công Tắc Cảm Ứng Thông Minh", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bảng điều khiển ACIS (hay công tắc cảm ứng thông minh ACIS) là thiết bị cốt lõi trong hệ sinh thái giải pháp nhà thông minh của ACIS. Với thiết kế mặt kính cường lực sang trọng, kết hợp công nghệ cảm ứng điện dung siêu nhạy và giao tiếp không dây độc quyền, bảng điều khiển ACIS không chỉ thay thế hoàn toàn công tắc cơ truyền thống mà còn nâng tầm thẩm mỹ, cho phép người dùng điều khiển hệ thống chiếu sáng, rèm cửa, điều hòa từ xa qua điện thoại hoặc bằng giọng nói.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Bảng Điều Khiển Cảm Ứng ACIS Nổi Bật", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ACIS sở hữu các dòng công tắc với ngôn ngữ thiết kế đa dạng, phù hợp với mọi phong cách kiến trúc từ cổ điển đến hiện đại:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Thiết Kế", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chất Liệu & Màu Sắc", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phân Khúc Không Gian", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "ACIS Luxury Series", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế viền nhôm nguyên khối cắt kim cương (CNC) tinh tế, sang trọng vượt trội.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kính cường lực đen/trắng, viền vàng/bạc.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự cao cấp, Penthouse, căn hộ hạng sang.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "ACIS Elegance Series", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế tràn viền hiện đại, tối giản, tạo cảm giác thanh lịch và liền mạch với mặt tường.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kính cường lực cao cấp đen hoặc trắng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nhà phố hiện đại, chung cư, văn phòng công ty.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Bảng điều khiển ngữ cảnh", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tích hợp điều khiển hàng loạt thiết bị cùng lúc chỉ bằng 1 nút chạm (Ví dụ: Nút \\"Đi ngủ\\", \\"Tiệc tùng\\").", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kính cường lực phối LED định vị vị trí nút.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặt ở đầu giường ngủ, cửa ra vào phòng khách.", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Công Nghệ Độc Quyền Tạo Nên Khác Biệt Của ACIS", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ kết nối không dây độc quyền siêu ổn định", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Không sử dụng sóng Wi-Fi (dễ bị chập chờn khi nhà nhiều thiết bị) hay Zigbee thông thường, ACIS sử dụng công nghệ giao tiếp không dây tự phát triển (Mesh Network).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ này giúp các bảng điều khiển tự động truyền tín hiệu cho nhau, đảm bảo ", "type": "text"}, {"text": "xuyên tường bê tông cực tốt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", sóng phủ đều toàn bộ ngôi nhà từ tầng hầm lên sân thượng mà không bị trễ.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. An toàn điện và độ bền cơ học tối đa", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cách ly điện tuyệt đối:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Mặt kính cường lực chống trầy xước, chống va đập và cách điện hoàn toàn. Người dùng có thể vô tư chạm tay ướt để điều khiển mà không sợ rò rỉ điện.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Linh kiện cao cấp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khối công suất bên trong sử dụng linh kiện chất lượng cao, chịu tải lớn, giải quyết triệt để tình trạng chập cháy hay dính tiếp điểm khi bật tắt các thiết bị công suất cao như đèn chùm, bơm nước.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Tính Năng Thông Minh Trên Bảng Điều Khiển ACIS", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Đèn LED định vị ban đêm:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Mỗi nút cảm ứng đều có đèn LED đổi màu (xanh/đỏ) dịu nhẹ, giúp người dùng dễ dàng xác định vị trí công tắc trong bóng tối mà không gây chói mắt khi ngủ.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kích hoạt kịch bản thông minh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thay vì phải đi bật từng bóng đèn, người dùng chỉ cần chạm nhẹ 1 nút trên bảng điều khiển để tắt toàn bộ đèn trong nhà hoặc mở hệ thống rèm cửa.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Đồng bộ trạng thái thời gian thực:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Trạng thái Bật/Tắt trên bảng điều khiển sẽ cập nhật ngay lập tức lên ứng dụng điện thoại, giúp bạn kiểm soát ngôi nhà chính xác dù đang ở bất cứ đâu.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Lưu Ý Quan Trọng Khi Khảo Sát Và Thi Công", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tương thích đế âm tường tiêu chuẩn:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Bảng điều khiển ACIS được thiết kế theo kích thước chuẩn (Hình chữ nhật hoặc Hình vuông) phù hợp với các loại đế âm tường thông dụng trên thị trường (như Sino, Panasonic). Chủ nhà có thể nâng cấp từ nhà thường lên nhà thông minh mà ", "type": "text"}, {"text": "không cần đục phá tường", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Yêu cầu dây nguội (Dây N):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giống như hầu hết các dòng công tắc thông minh cao cấp, bảng điều khiển ACIS yêu cầu phải có dây nguội (dây N) tại vị trí hộp công tắc để cấp nguồn cho mạch cảm ứng hoạt động ổn định liên tục.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'bang-dieu-khien';
UPDATE categories SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Giấu Trần Nối Ống Gió: Đỉnh Cao Thẩm Mỹ Và Làm Mát Sang Trọng", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió (hay điều hòa âm trần nối ống gió) là hệ thống làm mát cao cấp nhất hiện nay. Khác với các dòng máy lộ mặt nạ, loại máy này được lắp giấu hoàn toàn trên trần thạch cao. Hơi lạnh từ dàn lạnh sẽ được dẫn qua hệ thống ống gió tôn/vải và thổi ra ngoài thông qua các cửa gió (miệng gió) được thiết kế đa dạng, hài hòa tuyệt đối với không gian nội thất.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Thương Hiệu Máy Lạnh Giấu Trần Nối Ống Gió Hàng Đầu", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thương Hiệu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Nổi Bật", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Áp Suất Tĩnh (ESP)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phân Khúc Giá", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Daikin", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dẫn đầu thị trường, dải công suất cực rộng, máy chạy siêu êm và bền bỉ", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Từ thấp đến cao (thích hợp mọi loại trần)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Panasonic", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lọc không khí Nanoe-X bảo vệ sức khỏe, thiết kế dàn lạnh mỏng nhẹ dễ lắp", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trung bình đến Cao", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mitsubishi Heavy", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Khả năng làm lạnh sâu, hoạt động bền bỉ trong điều kiện khắc nghiệt", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Áp suất tĩnh cao, thổi gió rất xa", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "LG", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá thành cạnh tranh, thiết kế thông minh, tích hợp sẵn bơm nước ngưng", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trung bình", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tầm trung", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Phân Loại Theo Áp Suất Tĩnh (ESP) - Yếu Tố Kỹ Thuật Cần Biết", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Áp suất tĩnh thấp (Low Static Pressure):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dàn lạnh cực mỏng (chỉ khoảng 200mm). Phù hợp cho phòng ngủ căn hộ, khách sạn có không gian trần hẹp, ống gió đi ngắn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Áp suất tĩnh trung bình (Middle Static Pressure):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dòng phổ biến nhất. Phù hợp cho phòng khách lớn, văn phòng, nhà hàng nơi cần chia ra từ 2 đến 4 cửa gió.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Áp suất tĩnh cao (High Static Pressure):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Máy có lực thổi cực mạnh. Phù hợp cho các không gian siêu rộng, trần rất cao hoặc ống gió cần đi ngoằn ngoèo, đi xa.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Lý Do Máy Lạnh Giấu Trần Nối Ống Gió Được Giới Thượng Lưu Ưa Chuộng", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tính thẩm mỹ độc bản:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Không còn một chiếc máy thô kệch treo trên tường. Người dùng hoặc kiến trúc sư có thể tự do chọn kiểu dáng cửa gió (cửa gió dạng khe dài Linear, cửa gió tròn, cửa gió khuếch tán) để biến nó thành một chi tiết decor sang trọng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Làm mát đa điểm, dịu nhẹ:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Một dàn lạnh có thể chia ra nhiều ống gió để thổi xuống nhiều vị trí khác nhau trong phòng hoặc chia sang phòng bên cạnh. Luồng gió đi qua đường ống nên hơi lạnh rất dịu, không bị buốt cục bộ.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tiết kiệm không gian tối đa:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giúp tối ưu hóa khoảng trống trên tường và sàn nhà, cực kỳ thích hợp cho các căn hộ penthouse có vách kính full trần.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Quy Trình Và Lưu Ý Bắt Buộc Khi Lắp Đặt", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lên bản vẽ thiết kế từ sớm:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phải bố trí vị trí đặt máy, hướng đi của ống gió và vị trí cửa gió ngay từ công đoạn phần thô của ngôi nhà.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tính toán khoảng hạ trần (Khoảng trống trần):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Độ cao của trần thạch cao phải hạ xuống từ 25cm - 35cm để vừa vặn cho phần thân máy và hộp gió.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bố trí cửa thăm trần (Lỗ thăm):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đây là lưu ý cốt lõi để ăn điểm SEO. Phải thiết kế một ô cửa thăm trần nhỏ ngay vị trí bo mạch máy để kỹ thuật viên có thể sửa chữa, bảo dưỡng sau này mà không phải đập bỏ trần thạch cao.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cách âm hộp gió:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Vì máy giấu trên trần, nếu không bọc cách âm tiêu âm tốt cho hộp gió và ống gió, tiếng gió rít có thể gây khó chịu khi ngủ.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'may-lanh-giau-tran-noi-ong-gio';
UPDATE categories SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Áp Trần: Giải Pháp Làm Lạnh Mạnh Mẽ Cho Không Gian Trần Cao", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy lạnh áp trần (Ceiling Suspended) là dòng máy lạnh thương mại được lắp đặt áp sát vào bề mặt trần nhà bê tông hoặc trần thạch cao, thay vì giấu bên trong trần như máy âm trần. Với thiết kế dàn lạnh phẳng, mỏng và ôm sát trần, dòng máy này sở hữu hệ thống cánh quạt cùng cửa gió lớn, mang lại khả năng phân phối luồng gió mát mạnh mẽ, thổi xa và rộng khắp không gian có diện tích lớn.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Thương Hiệu Máy Lạnh Áp Trần Hàng Đầu Thị Trường", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thương Hiệu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thế Mạnh Cốt Lõi", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Luồng Gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phân Khúc Giá", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Daikin", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Độ bền công nghiệp vượt trội, dải công suất rộng, máy chạy êm và tiết kiệm điện tốt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gió thổi xa lên đến 15 mét, có góc đảo gió rộng (lên/xuống, trái/phải).", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Panasonic", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế thanh lịch thời trang, tích hợp công nghệ lọc khí độc quyền Nanoe-X bảo vệ sức khỏe.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Luồng gió thổi dễ chịu, phân bổ đều khắp phòng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "LG", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kiểu dáng hiện đại đoạt giải thưởng thiết kế, công nghệ Smart Inverter tối ưu chi phí vận hành.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Luồng gió mạnh mẽ, có khả năng làm lạnh cực nhanh.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tầm trung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Reetech / Casper", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá thành rẻ, chi phí đầu tư ban đầu thấp, khả năng làm lạnh bền bỉ ở môi trường khắc nghiệt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thổi gió trực diện, mạnh mẽ.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá rẻ", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Phân Loại Công Suất Máy Lạnh Áp Trần Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Do đặc thù phục vụ cho không gian thương mại và công cộng, máy áp trần thường có dải công suất lớn từ 2 HP trở lên:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP) - 24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho không gian từ ", "type": "text"}, {"text": "20 - 35m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Văn phòng nhỏ, lớp học gia sư, shop thời trang mini).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "36.000 Btu/h (4 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "35 - 50m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Showroom trưng bày, quán cafe, văn phòng làm việc tầm trung).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "45.000 Btu/h (5 HP) - 50.000 Btu/h (5.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "50 - 70m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Giảng đường đại học, nhà hàng ăn uống, hội trường).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "60.000 Btu/h (6 HP) trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dòng công nghiệp dùng cho diện tích ", "type": "text"}, {"text": "trên 75m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Nhà xưởng, không gian thông tầng siêu rộng).", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Lý Do Máy Lạnh Áp Trần Được Lựa Chọn Lắp Đặt", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sức mạnh làm lạnh vượt trội:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nhờ cửa gió rộng và quạt lồng sóc công suất lớn, máy áp trần tạo ra lưu lượng gió mạnh hơn hẳn dòng treo tường hay âm trần có cùng công suất. Hơi lạnh được đẩy đi xa, luân chuyển đều, không bị hiện tượng góc chết.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Không tốn khoảng trống hạ trần thạch cao:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nếu trần nhà bạn là trần bê tông phẳng hoặc bạn thích phong cách thiết kế công nghiệp (Industrial style) để lộ trần, máy áp trần là lựa chọn hoàn hảo vì nó bắt vít trực tiếp lên trần, thi công rất nhanh.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dễ dàng bảo dưỡng, vệ sinh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Do toàn bộ máy lộ ra ngoài, việc tháo mặt nạ để rửa lưới lọc bụi hay kiểm tra bo mạch, block máy cực kỳ dễ dàng, giúp tiết kiệm chi phí bảo trì định kỳ.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Một Số Lưu Ý Kỹ Thuật Quan Trọng Khi Lắp Đặt", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kiểm tra độ cao và khả năng chịu lực của trần:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dàn lạnh áp trần thường khá nặng (từ 25kg - 50kg tùy công suất). Trần nhà cần chắc chắn để bắt ty treo gia cố. Máy nên được lắp ở độ cao từ 2.7m - 3.5m để luồng gió tản đều, không thổi thẳng vào đầu người dùng gây buốt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Xử lý đường ống nước ngưng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khác với dòng âm trần thường tích hợp sẵn bơm nước ngưng để đẩy nước lên cao, một số dòng áp trần tiêu chuẩn sử dụng cơ chế thoát nước tự nhiên bằng độ dốc. Thợ kỹ thuật cần tính toán đường đi của ống nước để tránh bị tràn hoặc đọng nước.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ưu tiên dòng Inverter cho không gian kinh doanh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nếu lắp cho văn phòng hoặc quán ăn mở cửa 10-12 tiếng/ngày, hãy tư vấn khách chọn dòng Inverter để giảm tải hóa đơn tiền điện, dù chi phí mua máy ban đầu sẽ nhỉnh hơn dòng máy cơ.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'may-lanh-ap-tran';
UPDATE categories SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cảm Biến Thông Minh: Linh Hồn Của Hệ Thống Tự Động Hóa Smarthome", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Cảm biến thông minh (Smart Sensor) là các thiết bị đầu vào có nhiệm vụ thu thập dữ liệu từ môi trường xung quanh (chuyển động, ánh sáng, nhiệt độ, độ ẩm, trạng thái cửa...) và truyền tín hiệu về bộ điều khiển trung tâm. Trong hệ sinh thái nhà thông minh, cảm biến chính là nhân tố cốt lõi giúp kích hoạt các kịch bản tự động hóa hoàn toàn mà không cần sự can thiệp của con người, mang lại cuộc sống tiện nghi, an toàn và tiết kiệm năng lượng.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Cảm Biến Thông Minh Phổ Biến Trong Hệ Thống Smarthome", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Mỗi loại cảm biến đóng một vai trò riêng biệt để bảo vệ và phục vụ đời sống gia đình:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Loại Cảm Biến", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chức Năng Cốt Lõi", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kịch Bản Ứng Dụng Thực Tế", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cảm biến chuyển động (Motion Sensor)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phát hiện có sự di chuyển của con người trong vùng quét.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tự động bật đèn cầu thang/nhà vệ sinh khi có người đi vào và tắt khi họ đi ra. Tránh lãng phí điện.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cảm biến cửa (Door/Window Sensor)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phát hiện trạng thái Đóng hoặc Mở của cửa chính, cửa sổ.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phát cảnh báo đến điện thoại khi có người cạy cửa ban đêm. Tự động tắt máy lạnh nếu cửa sổ mở quá 3 phút.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cảm biến hiện diện (Presence Sensor)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Sử dụng công nghệ radar (mmWave) để phát hiện người ngồi im, nằm ngủ (vượt trội hơn cảm biến chuyển động).", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giữ cho đèn phòng làm việc hoặc phòng khách luôn bật dù người dùng đang ngồi đọc sách, không di chuyển.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cảm biến môi trường (Nhiệt độ - Độ ẩm)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đo đạc chính xác các chỉ số không khí trong phòng theo thời gian thực.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tự động bật máy hút ẩm khi trời nồm, hoặc tự tăng nhiệt độ máy lạnh vào lúc 3 giờ sáng để bảo vệ sức khỏe.", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Lợi Ích Vượt Trội Khi Kết Hợp Cảm Biến Vào Hệ Sinh Thái ACIS", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tự động hóa không độ trễ:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nhờ công nghệ mạng Mesh độc quyền của ACIS, khi cảm biến phát hiện tín hiệu (ví dụ: có người bước vào hành lang), lệnh sẽ được truyền ", "type": "text"}, {"text": "ngay lập tức", "type": "text", "marks": [{"type": "italic"}]}, {"text": " đến công tắc đèn mà không gặp tình trạng trễ mạng như các dòng Wi-Fi thông thường.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bảo mật và an ninh 24/7:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tạo lập hàng rào an ninh đa lớp. Khi bạn kích hoạt chế độ \\"An ninh\\", cảm biến cửa và cảm biến chuyển động ngoài sân sẽ tự động kích hoạt. Nếu có đột nhập, hệ thống sẽ tự động bật camera, hú còi và chớp nháy toàn bộ đèn trong nhà để đuổi trộm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tối ưu hóa hóa đơn tiền điện:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Rất nhiều gia đình bật điều hòa, đèn phòng khách rồi đi ra ngoài quên tắt. Cảm biến thông minh sẽ nhận biết không gian trống trong vòng 15-20 phút để tự động ra lệnh tắt toàn bộ thiết bị điện.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tiêu Chí Lắp Đặt Và Bố Trí Cảm Biến Chuẩn Kỹ Thuật", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Vị trí lắp đặt cảm biến chuyển động:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nên đặt ở góc trần nhà hoặc tường cao (khoảng 2m - 2.5m) để có góc quét rộng nhất. Tránh hướng mắt cảm biến trực tiếp vào cục nóng máy lạnh, cửa sổ có rèm lay động hoặc nơi thú cưng hay chạy qua để tránh báo động giả.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lựa chọn nguồn cấp (Pin vs Điện lưới):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Hầu hết cảm biến thông minh hiện nay sử dụng Pin (Lithium dung lượng cao) để dễ dàng dán lên tường, trần mà không cần đi dây điện. Tuổi thọ pin thường kéo dài từ 1 - 2 năm và sẽ có cảnh báo pin yếu về ứng dụng điện thoại để chủ nhà chủ động thay thế.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'cam-bien-thong-minh';
UPDATE categories SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Âm Trần Đa Hướng Thổi: Giải Pháp Làm Mát 360 Độ Toàn Diện", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy lạnh âm trần đa hướng thổi (hay điều hòa âm trần 360 độ / đa hướng gió) là dòng máy lạnh được thiết kế phần mặt nạ (panel) có khả năng phân phối luồng gió ra khắp mọi hướng (4 hướng, 8 hướng hoặc thổi tròn 360 độ). Toàn bộ thân máy được giấu hoàn toàn bên trong trần thạch cao, chỉ lộ ra phần mặt nạ thổi gió phẳng, mang lại sự sang trọng, đẳng cấp và tối ưu diện tích cho không gian rộng.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Thương Hiệu Máy Lạnh Âm Trần Đa Hướng Thổi Nổi Tiếng", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thương Thương Hiệu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Số Hướng Thổi & Đặc Điểm", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công Nghệ Nổi Bật", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phân Khúc Giá", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Daikin", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thổi tròn 360 độ (Đa hướng cảm biến)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Luồng gió tuần hoàn, Cảm biến hồng ngoại kép (phát hiện người), Kháng khuẩn Ion bạc", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Panasonic", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thổi 4 hướng / Đa hướng rộng", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lọc khí Nanoe-X thế hệ mới, Cánh đảo gió rộng phẳng giúp thổi xa hơn", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "LG", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thổi đa hướng độc lập (4 cánh chỉnh riêng)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mặt nạ lọc bụi mịn PM1.0, Động cơ BLDC siêu êm, Điều khiển qua Wi-Fi ThinQ", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tầm trung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Samsung", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thổi tròn 360 độ (Cassette 360)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ WindFree (làm lạnh không gió buốt), Thiết kế tròn bo cong độc đáo", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Cao cấp", "type": "text"}]}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Công Suất Và Diện Tích Lắp Đặt Máy Lạnh Âm Trần", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dòng máy âm trần thường có công suất lớn để phục vụ các không gian rộng lớn hoặc có trần cao.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dùng cho không gian rộng từ ", "type": "text"}, {"text": "20 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách chung cư cao cấp, phòng họp nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP) - 30.000 Btu/h (3.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dùng cho không gian từ ", "type": "text"}, {"text": "30 - 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, showroom nhỏ, shop thời trang).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "36.000 Btu/h (4 HP) - 42.000 Btu/h (4.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dùng cho diện tích từ ", "type": "text"}, {"text": "45 - 60m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Văn phòng làm việc đông người, sảnh tiệc).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "48.000 Btu/h (5 HP) - 50.000 Btu/h (5.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dùng cho diện tích ", "type": "text"}, {"text": "trên 60m2 đến 75m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Nhà hàng lớn, trung tâm hội nghị).", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Ưu Điểm Vượt Trội Của Máy Lạnh Âm Trần Đa Hướng Thổi", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Làm lạnh đồng đều, không góc chết:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khác với máy lạnh treo tường hay âm trần cũ chỉ thổi 1-2 hướng gây buốt một chỗ, dòng đa hướng thổi/360 độ phân bổ gió lạnh đi khắp phòng, giúp nhiệt độ đều và dễ chịu ở mọi vị trí.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tính thẩm mỹ đỉnh cao:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Máy giấu trần giúp trần nhà trông thoáng đãng, hiện đại. Đặc biệt các dòng Cassette tròn của Samsung hay Daikin có thể phối hợp hoàn hảo với thiết kế nội thất của kiến trúc sư.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tiết kiệm diện tích sàn và tường:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thích hợp cho các cửa hàng trưng bày, showroom hoặc văn phòng vì không chiếm khoảng trống trên tường để treo tranh, kệ hay decor.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tiêu Chí Chọn Mua Và Lắp Đặt Cho Doanh Nghiệp & Gia Đình", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Khảo sát độ cao của trần nhà:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Máy âm trần cần khoảng trống phía trên trần thạch cao tối thiểu từ 25cm - 40cm (tùy công suất máy) để giấu phần thân máy. Nếu trần quá thấp sẽ không lắp được.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tính toán tải nhiệt không gian:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Quán cafe hoặc văn phòng có nhiều kính, nhiều máy tính và nhiều người ra vào cần phải chọn tăng 1 đến 2 cấp công suất so với phòng ngủ gia đình thông thường để máy không bị quá tải.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ưu tiên chọn dòng Inverter:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Vì dòng máy này công suất lớn và thường bật suốt cả ngày (nhất là kinh doanh dịch vụ), việc chọn dòng Inverter sẽ giúp cắt giảm từ 40% đến 50% chi phí hóa đơn tiền điện mỗi tháng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bố trí vị trí dàn nóng phù hợp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dàn nóng của máy âm trần rất to và nặng, cần chọn vị trí thông thoáng, chắc chắn bên ngoài tòa nhà để máy tản nhiệt tốt.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'may-lanh-am-tran-da-huong-thoi';
UPDATE categories SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Remote Cầm Tay Thông Minh: Tiện Ích Chạm Nhanh Cho Mọi Thành Viên", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Remote cầm tay thông minh (hay remote điều khiển ngữ cảnh) là thiết bị điều khiển từ xa bỏ túi, cho phép người dùng kích hoạt nhanh các kịch bản sống trong hệ thống Smarthome mà không cần dùng đến điện thoại hay máy tính bảng. Với thiết kế nhỏ gọn, thời lượng pin dài và khả năng liên kết trực tiếp với các thiết bị trong mạng Mesh, remote cầm tay là giải pháp hoàn hảo mang lại sự tiện lợi tức thì cho mọi thành viên trong gia đình, đặc biệt là người lớn tuổi và trẻ nhỏ.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Ứng Dụng Thực Tế Của Remote Cầm Tay Trong Nhà Thông Minh", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khác với chiếc remote tivi hay máy lạnh thông thường chỉ điều khiển được một thiết bị, remote thông minh điều khiển được ", "type": "text"}, {"text": "hàng loạt thiết bị cùng lúc", "type": "text", "marks": [{"type": "bold"}]}, {"text": " thông qua kịch bản lập trình sẵn:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Đặt ở tủ đầu giường ngủ:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tích hợp nút \\"Đi ngủ\\" – nhấn 1 phát tự động tắt hết đèn phòng khách, hạ rèm, bật máy lạnh phòng ngủ và kích hoạt chế độ an ninh ban đêm. Không cần phải bước ra khỏi chăn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Treo ngay chùm chìa khóa xe:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tích hợp nút \\"Về nhà\\" hoặc \\"Ra ngoài\\". Trước khi dắt xe ra khỏi cổng, nhấn 1 nút để tắt toàn bộ hệ thống điện. Khi đi làm về, nhấn nút để mở cổng tự động, bật đèn sân và phòng khách.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dành riêng cho người già và trẻ nhỏ:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Người lớn tuổi thường ngại sử dụng smartphone vì thao tác phức tạp. Một chiếc remote cầm tay với các nút nhấn vật lý rõ ràng giúp họ bật/tắt đèn, quạt hoặc gọi hỗ trợ khẩn cấp (SOS) một cách dễ dàng nhất.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Ưu Điểm Vượt Trội Của Remote Cầm Tay ACIS", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ kết nối local không độ trễ:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng sóng giao tiếp nội bộ độc quyền của ACIS. Khi nhấn nút, tín hiệu truyền thẳng đến bộ điều khiển trung tâm và các công tắc mà không cần đi vòng qua Internet, tốc độ phản hồi chỉ trong phần triệu giây.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hoạt động hoàn hảo khi mất Internet/Wi-Fi:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đây là điểm ăn tiền lớn nhất. Nếu nhà bị đứt cáp quang hoặc modem Wi-Fi bị treo, app điện thoại không mở được thì chiếc remote cầm tay này vẫn điều khiển nhà cửa bình thường.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thời lượng pin siêu bền:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng pin lithium chuyên dụng kết hợp với chế độ tự động \\"ngủ sâu\\" khi không nhấn nút. Một viên pin có thể sử dụng liên tục từ 1 - 2 năm mới cần thay thế.", "type": "text"}]}]}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tiêu Chí Chọn Mua Và Phân Loại Remote Thông Minh", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chọn số lượng nút bấm theo nhu cầu:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Remote cầm tay thường có các dòng 2 nút, 4 nút hoặc nhiều hơn. Nếu chỉ cần tắt/mở cơ bản thì dòng 2-4 nút là vừa vặn, tránh quá nhiều nút gây rối cho người già.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chọn dòng có thiết kế chống nước/chống va đập:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Vì là thiết bị cầm tay dễ rơi rớt hoặc bỏ túi quần, nên ưu tiên các dòng remote có vỏ nhựa ABS cao cấp, viền bo cong và có khả năng chống ẩm nhẹ.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'remote-cam-tay';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Samsung: Tiên Phong Thiết Kế Đột Phá Và Công Nghệ Làm Lạnh Không Gió Buốt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Samsung là tập đoàn công nghệ toàn cầu đến từ Hàn Quốc, luôn đi đầu trong việc tái định nghĩa trải nghiệm người dùng bằng những phát minh mang tính cách mạng. Trong lĩnh vực điều hòa không khí, Samsung không chỉ gây ấn tượng mạnh mẽ bởi ngôn ngữ thiết kế thời trang, hiện đại mà còn khẳng định vị thế độc tôn nhờ công nghệ làm lạnh WindFree™ – giải pháp làm mát không gió buốt, bảo vệ sức khỏe toàn diện và tối ưu hóa năng lượng thông minh bằng công nghệ Digital Inverter Boost.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Samsung Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Samsung sở hữu dải sản phẩm điều hòa không khí đa dạng, đáp ứng trọn vẹn từ nhu cầu dân dụng đến các không gian thương mại và kiến trúc cao cấp:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Samsung", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế bo cong tinh tế hoặc tam giác độc đáo. Nổi bật với các dòng WindFree™ làm lạnh dịu nhẹ, vận hành siêu êm và tích hợp bộ lọc khí nâng cao.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ gia đình, phòng khách nhỏ, căn hộ chung cư, phòng làm việc cá nhân.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đột phá với dòng ", "type": "text"}, {"text": "Cassette 360", "type": "text", "marks": [{"type": "bold"}]}, {"text": " thổi tròn độc bản (thiết kế không cánh đảo gió) và dòng Cassette 4 hướng thổi WindFree™ sang trọng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán kinh doanh cafe nghệ thuật, showroom thời trang, nhà hàng, văn phòng cao cấp.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dàn lạnh siêu mỏng với thiết kế thông minh, áp suất tĩnh tự động điều chỉnh giúp tối ưu luồng gió và giấu kín thẩm mỹ tuyệt đối.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự biệt lập, Penthouse, căn hộ hạng sang, phòng khách lớn.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp sát vào trần bê tông hoặc trần giả, kết cấu mỏng nhẹ, thanh lịch nhưng sở hữu sức gió thổi mạnh mẽ, tản nhiệt diện rộng cực tốt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lớp học, giảng đường, cửa hàng tiện lợi, không gian trần thô phong cách tối giản.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kiểu dáng khối đặt sàn Slim siêu mỏng tinh tế như một tác phẩm nghệ thuật, lưu lượng gió cực đại thổi trực tiếp làm mát không gian rộng tức thì.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng, showroom lớn, trung tâm hội nghị, nhà xưởng sạch.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Đột Phá Nổi Bật Của Samsung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sự vượt trội giúp Samsung tạo nên dấu ấn riêng và cạnh tranh mạnh mẽ ở phân khúc cao cấp nằm ở các giải pháp công nghệ độc quyền hướng tới sự thoải mái tối đa:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ làm lạnh WindFree™ độc quyền không gió buốt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Đây là công nghệ mang tính cách mạng của Samsung. Khi phòng đã đạt nhiệt độ cài đặt, cửa gió sẽ đóng lại và hơi lạnh sẽ được khuếch tán nhẹ nhàng qua hàng chục ngàn lỗ nhỏ li ti (Micro-holes) trên mặt nạ dàn lạnh. Cơ chế này tạo ra luồng khí mát dịu nhẹ luân chuyển đều khắp phòng, hoàn toàn không thổi gió buốt trực tiếp vào người, loại bỏ hiện tượng lạnh tê buốt và bảo vệ hệ hô hấp cho người già, trẻ nhỏ.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Động cơ Digital Inverter Boost siêu tiết kiệm điện", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Samsung trang bị công nghệ Digital Inverter Boost sử dụng nam châm Neodymium và bộ giảm âm kép. Công nghệ này giúp máy nén duy trì tần số hoạt động cực kỳ ổn định, làm lạnh nhanh hơn đến 43% ngay khi vừa khởi động, giảm thiểu tối đa ma sát và tiếng ồn, đồng thời tiết kiệm điện năng tiêu thụ lên đến 73% so với các dòng máy cơ thông thường.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Hệ thống lọc khí nâng cao và Bộ lọc PM1.0 sạch khuẩn", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bộ lọc PM1.0:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tích hợp hệ thống lọc tĩnh điện mạnh mẽ, chủ động giữ lại và vô hiệu hóa các hạt bụi siêu mịn kích thước PM1.0, vi khuẩn và tác nhân gây dị ứng bơ lửng trong không khí.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bộ lọc Copper Anti-bacterial:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Màng lọc phủ tinh thể đồng kháng khuẩn, dễ dàng tháo rời để vệ sinh bằng nước, giúp giữ cho luồng khí thổi ra luôn sạch mùi và tinh khiết.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Tính năng tự động làm sạch 3 bước (Auto Clean)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sau khi tắt máy lạnh, tính năng Auto Clean sẽ tự động kích hoạt quạt gió thổi liên tục trong vòng 10 đến 30 phút để làm khô hoàn toàn hơi nước tích tụ và độ ẩm còn sót lại trên các lá nhôm tản nhiệt. Quá trình này giúp ngăn chặn tận gốc sự hình thành, phát triển của nấm mốc và vi khuẩn bám trong dàn lạnh.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Samsung Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lựa chọn đúng công suất giúp hệ thống máy lạnh vận hành tối ưu hiệu năng, máy nén không bị chạy quá tải và kéo dài tuổi thọ thiết bị:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng học nhỏ, phòng làm việc riêng).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách căn hộ nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách lớn, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, showroom trưng bày, cửa hàng kinh doanh).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành riêng cho các dòng máy thương mại công suất lớn (Âm trần Cassette 360, tủ đứng) lắp đặt cho không gian rộng ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'samsung';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Daikin: Thương Hiệu Dẫn Đầu Công Nghệ Làm Lạnh Biến Tần", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Daikin là thương hiệu điều hòa không khí hàng đầu thế giới đến từ Nhật Bản, nổi tiếng với sự chuyên nghiệp khi chỉ tập trung nghiên cứu và sản xuất các giải pháp làm mát. Tại thị trường Việt Nam, Daikin luôn là lựa chọn hàng đầu của cả người tiêu dùng dân dụng lẫn các chủ đầu tư dự án nhờ độ bền cơ học vượt trội, khả năng tiết kiệm điện dẫn đầu và dải sản phẩm cực kỳ đa dạng đáp ứng mọi nhu cầu kiến trúc.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Daikin Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Daikin sở hữu hệ sinh thái sản phẩm toàn diện, từ các giải pháp cục bộ cho phòng nhỏ đến hệ thống điều hòa trung tâm cho toàn bộ tòa nhà:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Daikin", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Cốt Lõi", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế thanh lịch, sở hữu các dòng FTKY, FTKB phổ biến. Khả năng vận hành siêu êm ái và lọc khí đỉnh cao.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ gia đình, phòng khách nhỏ, căn hộ chung cư, văn phòng cá nhân.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nổi bật với dòng mặt nạ thổi tròn 360 độ (Đa hướng thổi), tích hợp cảm biến hồng ngoại thông minh nhận diện người.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán kinh doanh cafe, nhà hàng, showroom thời trang, văn phòng làm việc lớn.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đỉnh cao về thẩm mỹ, thân máy giấu hoàn toàn trên trần, hơi lạnh dẫn qua các cửa gió Linear sang trọng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự cao cấp, Penthouse, khách sạn hạng sang, căn hộ chung cư cao cấp.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế mỏng áp sát trần bê tông, cửa gió lớn với sức gió thổi cực mạnh và xa lên đến 15 mét.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giảng đường đại học, lớp học, cửa hàng tiện lợi, không gian trần thô.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dạng tủ đặt sàn cơ động, công suất lớn từ 2.5 HP đến hơn 10 HP, tốc độ làm mát không gian rộng tức thì.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng, nhà xưởng, trung tâm tiệc cưới, hội trường lớn.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Đột Phá Làm Nên Tên Tuổi Của Daikin", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sự khác biệt giúp Daikin giữ vững ngôi vương trên thị trường điều hòa không khí nằm ở các công nghệ độc quyền hướng tới trải nghiệm người dùng:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Luồng gió Coanda dễ chịu bảo vệ sức khỏe", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khác với các dòng máy thông thường thổi gió trực tiếp vào người gây buốt, công nghệ Coanda của Daikin hướng luồng gió đi sát lên trần nhà rồi mới từ từ hạ xuống, bao phủ toàn bộ không gian. Cơ chế này tạo ra dòng khí mát nhẹ nhàng, tự nhiên và ngăn ngừa tối đa các bệnh về đường hô hấp.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Công nghệ biến tần Inverter kết hợp Máy nén Swing", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Daikin sử dụng công nghệ biến tần Inverter kết hợp với máy nén Swing độc quyền. Nhờ chuyển động quay tròn nhẹ nhàng của trục máy nén, hiện tượng ma sát và rò rỉ gas được giảm thiểu tối đa, giúp máy vận hành bền bỉ, êm ái đến mức gần như không nghe thấy tiếng động và tiết kiệm điện năng vượt trội.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Phin lọc Enzyme Blue và Công nghệ Streamer sạch khuẩn", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Enzyme Blue:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Lớp lọc tiêu chuẩn có khả năng khử mùi hôi, loại bỏ các tác nhân gây dị ứng và ức chế sự phát triển của vi khuẩn, virus.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ Streamer:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giải phóng các dòng electron tốc độ cao để phân hủy vi khuẩn và nấm mốc bám trên phin lọc, tự động làm sạch dàn lạnh giúp luồng khí thổi ra luôn tinh khiết.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Dàn tản nhiệt chống ăn mòn và Cánh tản nhiệt Microchannel", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Các cánh tản nhiệt của dàn nóng Daikin được phủ lớp nhựa acrylic đặc biệt giúp chống lại mưa axit, hơi muối và sự ăn mòn của thời tiết. Phiên bản Microchannel sử dụng hợp kim nhôm gia tăng hiệu suất trao đổi nhiệt và kéo dài tuổi thọ thiết bị tối đa.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Tính Công Suất Lắp Đặt Máy Lạnh Daikin Chuẩn Xác", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lựa chọn đúng công suất theo diện tích giúp tối ưu hóa hiệu năng và kéo dài tuổi thọ cho hệ thống máy lạnh Daikin:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng đọc sách).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng làm việc chung).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách chung cư, phòng họp nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách liền bếp, cửa hàng kinh doanh).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành cho các dòng máy thương mại (Âm trần, giấu trần, tủ đứng) lắp ở không gian lớn ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'daikin';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Gree: Thương Hiệu Điều Hòa Toàn Cầu Với Độ Bền Vượt Trội Và Chi Phí Tối Ưu", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Gree là tập đoàn sản xuất điều hòa không khí lớn nhất thế giới đến từ Trung Quốc, sở hữu năng lực sản xuất khổng lồ và làm chủ quy trình công nghệ từ linh kiện đến block máy nén. Tại thị trường Việt Nam, máy lạnh Gree khẳng định vị thế vững chắc nhờ triết lý sản xuất chú trọng vào độ bền bỉ cơ học (nồi đồng cối đá), khả năng làm lạnh mạnh mẽ, ổn định và mức giá thành cực kỳ hợp lý so với chất lượng mang lại. Đây là lựa chọn tối ưu cho những ai tìm kiếm giải pháp làm mát lâu dài, tiết kiệm chi phí đầu tư ban đầu và vận hành.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Gree Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Gree cung cấp dải sản phẩm điều hòa không khí đa dạng, phục vụ trọn vẹn từ các công trình dân dụng đến hệ thống thương mại công suất lớn:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Gree", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế nguyên khối chắc chắn, kiểu dáng tinh tế. Nổi bật với các dòng Real Inverter siêu tiết kiệm điện, máy vận hành êm và làm lạnh rất sâu.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ gia đình, phòng trọ, căn hộ chung cư, văn phòng cá nhân.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế mặt nạ 4 hướng thổi gió đồng đều, tích hợp sẵn bơm nước ngưng công suất lớn và thiết kế mỏng nhẹ dễ lắp đặt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán kinh doanh cafe, nhà hàng, showroom thời trang, văn phòng công ty.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giải pháp thẩm mỹ cao cấp với dải áp suất tĩnh linh hoạt, khả năng đi ống gió xa thổi mát đều toàn bộ không gian giấu kín.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự, Penthouse, căn hộ cao cấp lớn, nhà hàng tiệc cưới.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp áp sát vào bề mặt trần bê tông, kết cấu máy cứng cáp chịu tải tốt, cửa gió rộng cho sức gió thổi cực mạnh và xa.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giảng đường, trường học, cửa hàng tiện lợi, không gian trần thô.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế khối đặt sàn vững chãi, lưu lượng gió cực đại thổi trực tiếp giúp hạ nhiệt độ không gian rộng lớn chỉ trong vài phút.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng lớn, showroom ô tô, nhà xưởng, sảnh đón khách.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Cốt Lõi Tạo Nên Uy Tín Của Gree", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sự vượt trội giúp máy lạnh Gree duy trì lòng tin tuyệt đối của người tiêu dùng nằm ở năng lực tự chủ công nghệ hướng tới độ bền lâu dài và hiệu suất tối ưu:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ biến tần Real Inverter độc quyền", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Gree trang bị công nghệ biến tần Real Inverter thế hệ mới được tích hợp bộ vi xử lý thông minh. Công nghệ này cho phép máy nén hoạt động ở tần số cực thấp (chỉ 1Hz), giúp tối ưu hóa lượng điện năng tiêu thụ lên đến 60% so với các dòng máy cơ thông thường, đồng thời duy trì nhiệt độ phòng luôn ổn định ở mức dễ chịu nhất mà không bị ngắt quãng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Chế độ làm lạnh siêu tốc Turbo", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khi kích hoạt chế độ Turbo trên remote, máy lạnh Gree sẽ lập tức đẩy công suất hoạt động của máy nén và quạt gió lên mức tối đa. Lưu lượng gió lớn sẽ nhanh chóng bao phủ toàn bộ căn phòng, hạ nhiệt độ phòng xuống mức cài đặt chỉ trong vòng 3 phút, giải tỏa ngay lập tức cảm giác oi bức.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Công nghệ làm sạch tự động G-Clean 4 bước", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống tự động kích hoạt quy trình làm sạch sâu dàn lạnh thông qua 4 bước tiêu chuẩn: Đóng băng (giữ bụi bẩn) -> Rã đông (cuốn trôi bụi bẩn) -> Sấy khô (ở nhiệt độ cao) -> Khử trùng. Quá trình này giúp loại bỏ hoàn toàn vi khuẩn, nấm mốc bám trên các lá nhôm tản nhiệt, giữ cho luồng khí luôn sạch mùi và tinh khiết.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Dàn tản nhiệt chống ăn mòn cao cấp Golden Fin", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dàn nóng ngoài trời của Gree được trang bị lớp phủ chống ăn mòn cao cấp Golden Fin màu vàng trên các cánh tản nhiệt. Lớp bảo vệ này giúp thiết bị chống chịu tốt trước các tác nhân khắc nghiệt của thời tiết như mưa axit, hơi muối biển và sự oxy hóa tự nhiên, bảo vệ tối đa block máy bên trong.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Gree Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lựa chọn đúng công suất giúp hệ thống máy lạnh vận hành ổn định, máy nén không bị chạy quá tải và kéo dài tuổi thọ thiết bị:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng học nhỏ, phòng trọ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách căn hộ nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách lớn, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, showroom trưng bày, cửa hàng kinh doanh).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành riêng cho các dòng máy thương mại công suất lớn (Âm trần, tủ đứng) lắp đặt cho các không gian rộng lớn ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'gree';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hệ Thống Giải Pháp Nhập Khẩu Menred: Đỉnh Cao Công Nghệ Đức Cho Smarthome Và Tiện Nghi Cơ Điện", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Menred (thành lập từ năm 1995 tại Đức) là thương hiệu toàn cầu dẫn đầu trong lĩnh vực nghiên cứu và sản xuất các thiết bị tự động hóa tòa nhà, hệ thống xử lý nước và thông gió thông minh. Định vị ở phân khúc cao cấp, các giải pháp của Menred được ứng dụng rộng rãi trong các dự án biệt thự, penthouse, căn hộ hạng sang và văn phòng hiện đại, mang lại một hệ sinh thái sống xanh, thông minh và an toàn tuyệt đối cho sức khỏe.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Danh Mục Giải Pháp Cốt Lõi Của Menred Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ sinh thái sản phẩm Menred tập trung giải quyết toàn diện ba yếu tố thiết yếu nhất của một ngôi nhà cao cấp: Không khí sạch, Nước tinh khiết và Điều khiển thông minh.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Hệ Thống Cấp Khí Tươi & Lọc Không Khí Khử Khuẩn (ERV/HRV)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Đây là giải pháp thông gió thu hồi nhiệt đỉnh cao, giải quyết triệt để tình trạng phòng kín bị ngộp khí, thiếu oxy hoặc tích tụ khí CO2 gây đau đầu, mệt mỏi khi ngủ dậy.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy cấp khí tươi âm trần (Central ERV):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giấu hoàn toàn trên trần thạch cao, đi ống gió đa điểm đến từng phòng, tích hợp bộ trao đổi nhiệt giúp bảo toàn đến 80% hơi lạnh của điều hòa và màng lọc HEPA H13 khử 99.97% bụi mịn PM2.5.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy cấp khí tươi treo tường:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thiết kế gọn gàng, lắp đặt nhanh chóng bằng cách khoan tường trực tiếp, phù hợp cho các căn hộ chung cư hoặc phòng ngủ đã hoàn thiện xong xuôi.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Hệ Thống Lọc Nước Cao Cấp (Water Purification)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Menred cung cấp các dòng máy lọc nước đặt âm tủ bếp (Under-sink) công suất lớn và hệ thống lọc nước trung tâm đầu nguồn giúp bảo vệ sức khỏe cho cả gia đình.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ Thẩm thấu ngược RO (Dòng Weißwasser RO, Rhine, Alpsee):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Loại bỏ hoàn toàn kim loại nặng (chì, thủy ngân, asen), vi khuẩn, hóa chất. Thiết kế không bình chứa (Tankless) giúp nước luôn tươi mới, không bị tái nhiễm khuẩn và tiết kiệm 70% không gian tủ bếp.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ Siêu lọc UF (Dòng Weißwasser UF WU2.SH01):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Hoạt động hoàn toàn không cần dùng điện, không có nước thải, loại bỏ tạp chất và vi khuẩn nhưng giữ lại nguyên vẹn các khoáng chất tự nhiên có lợi cho cơ thể.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Thiết Bị Kiểm Soát Khí Hậu & Tự Động Hóa Tòa Nhà (BMS / Smarthome)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Menred nổi tiếng thế giới với các dòng thiết bị điều khiển nhiệt độ, hệ thống sưởi sàn và tự động hóa hệ thống HVAC (Thông gió - Điều hòa - Sưởi ấm).", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bảng điều khiển nhiệt độ thông minh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Màn hình cảm ứng độ nét cao, thiết kế tinh tế giúp kiểm soát chính xác nhiệt độ từng phòng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống van và bộ điều khiển trung tâm:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Vận hành bền bỉ theo tiêu chuẩn công nghiệp Đức, tối ưu hóa năng lượng tiêu thụ cho toàn bộ hệ thống cơ điện trong tòa nhà.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Ưu Điểm Vượt Trội Khiến Giới Thượng Lưu Lựa Chọn Menred", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tiêu chuẩn chất lượng Đức (German Quality):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Mỗi sản phẩm trước khi xuất xưởng đều phải trải qua các quy trình kiểm định nghiêm ngặt của châu Âu, đảm bảo tuổi thọ thiết bị kéo dài hàng chục năm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tối ưu hóa năng lượng tối đa:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đi đầu trong xu hướng công nghệ xanh, các hệ thống ERV hay van điều khiển của Menred đều được thiết kế để cắt giảm từ 30% đến 50% chi phí điện năng vận hành cho hệ thống điều hòa và sưởi.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế tinh tế, tối giản:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ngoại hình sản phẩm được chăm chút tỉ mỉ với các đường nét tinh xảo, phối hợp hoàn hảo với các phong cách thiết kế nội thất từ hiện đại, tối giản đến sang trọng, đẳng cấp.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'menred';
UPDATE brands SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Toshiba: Đỉnh Cao Công Nghệ Nhật Bản Và Giải Pháp Chống Bám Bẩn Vượt Trội", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Toshiba là thương hiệu điện tử, điện lạnh lâu đời và uy tín bậc nhất đến từ Nhật Bản. Tại thị trường Việt Nam, máy lạnh Toshiba luôn khẳng định vị thế vững chắc trong phân khúc cao cấp nhờ triết lý sản xuất bền bỉ, khả năng làm lạnh êm ái, sâu lắng và đặc biệt là công nghệ độc quyền bảo vệ dàn lạnh khỏi bụi bẩn. Đây là sự lựa chọn tối ưu cho các gia đình chú trọng đến độ bền lâu dài của thiết bị và chất lượng không khí sạch khuẩn.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Toshiba Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Toshiba cung cấp dải sản phẩm điều hòa không khí đa dạng, đáp ứng toàn diện từ nhu cầu dân dụng đến các giải pháp thương mại:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Toshiba", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế nguyên khối sang trọng, viền bo cong tinh tế. Sở hữu dòng Daiseikai cao cấp hoặc dòng Inverter thế hệ mới với khả năng vận hành siêu êm.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ gia đình, phòng khách nhỏ, căn hộ chung cư, phòng làm việc riêng.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mặt nạ phẳng hiện đại, thiết kế đa hướng thổi giúp phân bổ hơi lạnh đồng đều, tích hợp bơm nước ngưng công suất lớn.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán cafe kinh doanh, nhà hàng, showroom thời trang, văn phòng công ty.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dàn lạnh mỏng nhẹ gọn gàng, áp suất tĩnh linh hoạt dễ đi ống gió, mang lại không gian nội thất đẳng cấp, giấu kín thẩm mỹ.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự, Penthouse, căn hộ chung cư hạng sang, phòng khách lớn.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp áp sát vào bề mặt trần bê tông, kết cấu máy cứng cáp, chịu được tần suất hoạt động liên tục với sức gió thổi mạnh mẽ.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trường học, giảng đường, cửa hàng tiện lợi, không gian phong cách Industrial.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kiểu dáng khối đặt sàn vững chãi, thời trang, lưu lượng gió cực đại thổi trực tiếp giúp hạ nhiệt độ không gian rộng lớn tức thì.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng lớn, showroom ô tô, nhà xưởng, sảnh đón khách.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Đột Phá Làm Nên Tên Tuổi Của Toshiba", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sự vượt trội giúp máy lạnh Toshiba duy trì lòng tin tuyệt đối của người tiêu dùng nằm ở các nền tảng công nghệ độc quyền hướng tới độ bền và sức khỏe sạch khuẩn:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ độc quyền Magic Coil chống bám bẩn", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Đây là công nghệ \\"đáng tiền\\" nhất của Toshiba. Dàn lạnh được phủ một lớp đặc biệt bằng chất liệu tổng hợp cao cấp, ngăn ngừa tối đa bụi bẩn, nấm mốc, dầu mỡ bám dính vào các lá nhôm tản nhiệt. Khi máy hoạt động, nước ngưng tụ sẽ tự động cuốn trôi mọi bụi bẩn ra ngoài theo đường ống thải. Công nghệ này giữ cho dàn lạnh luôn sạch sẽ, bảo toàn hiệu suất làm lạnh sâu và tiết kiệm chi phí vệ sinh định kỳ.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Công nghệ biến tần Hybrid Inverter tiết kiệm điện tối ưu", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Toshiba sử dụng hệ thống Hybrid Inverter tích hợp 2 mô-đun điều khiển riêng biệt: PAM (làm lạnh nhanh công suất lớn khi vừa khởi động) và PWM (duy trì nhiệt độ ổn định ở tần số thấp để tiết kiệm điện). Sự kết hợp này giúp máy đạt độ lạnh mong muốn cực nhanh, vận hành siêu êm và cắt giảm hóa đơn tiền điện lên đến 60% so với dòng máy cơ.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Hệ thống tinh lọc không khí Plasma Ion và Ultra Pure", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Plasma Ion:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chủ động tạo ra các ion mang điện tích âm để hút sạch khói thuốc, bụi bẩn bơ lửng, đồng thời tiêu hủy các tế bào vi khuẩn, vi-rút bám trên bề mặt để trả lại bầu không khí sạch khuẩn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bộ lọc Ultra Pure:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khả năng lọc sạch các hạt bụi mịn kích thước siêu nhỏ như PM2.5, khử các mùi hôi khó chịu và ức chế các tác nhân gây dị ứng.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Công nghệ tự làm sạch dàn lạnh Self-Cleaning", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sau khi tắt máy lạnh, quạt dàn lạnh bên trong sẽ tự động quay thêm từ 20 đến 30 phút để làm khô hoàn toàn lượng nước đọng dư thừa trên các lá nhôm. Quá trình này giúp ngăn chặn tận gốc sự hình thành của nấm mốc và vi khuẩn phát triển bên trong máy, loại bỏ mùi hôi ẩm mốc mỗi khi khởi động.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Toshiba Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lựa chọn đúng công suất giúp hệ thống máy lạnh vận hành ổn định, máy nén không bị quá tải và tối ưu hóa lượng điện tiêu thụ:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng học nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách căn hộ nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách lớn, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, showroom trưng bày, cửa hàng).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành riêng cho các dòng máy thương mại (Âm trần, giấu trần, tủ đứng) lắp đặt cho các không gian rộng lớn ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'toshiba';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Carrier: Thương Hiệu Phát Minh Ra Điều Hòa Không Khí Hiện Đại", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Carrier là thương hiệu điều hòa không khí lâu đời bậc nhất thế giới đến từ Mỹ, gắn liền với tên tuổi của Willis Carrier - người đã phát minh ra hệ thống điều hòa không khí hiện đại đầu tiên vào năm 1902. Với hơn một thế kỷ tiên phong và phát triển, dòng sản phẩm máy lạnh Carrier luôn khẳng định đẳng cấp hàng đầu trên toàn cầu nhờ nền tảng kỹ thuật cơ khí vững chắc, khả năng làm lạnh mạnh mẽ chuẩn Mỹ và độ bền bỉ thách thức thời gian. Đây là giải pháp làm mát tối ưu được các công trình lớn và các gia đình chú trọng độ bền tin dùng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Carrier Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Carrier cung cấp hệ thống giải pháp điều hòa toàn diện, từ các dòng máy dân dụng nhỏ gọn đến hệ thống máy thương mại công suất lớn:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Carrier", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế vuông vắn, cứng cáp theo phong cách Mỹ. Vận hành cực kỳ bền bỉ, làm lạnh sâu và mạnh mẽ.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ gia đình, phòng khách nhỏ, căn hộ chung cư, văn phòng cá nhân.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế mặt nạ đa hướng thổi gió rộng, tích hợp bơm nước ngưng công suất lớn và vận hành siêu êm ái.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán kinh doanh cafe, nhà hàng, showroom thời trang, văn phòng công ty.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giải pháp thẩm mỹ đỉnh cao với áp suất tĩnh linh hoạt, hệ thống máy chịu tải cực tốt, đi ống gió xa đến mọi góc phòng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự biệt lập, Penthouse, trung tâm hội nghị, căn hộ hạng sang lớn.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp sát vào bề mặt trần bê tông, kết cấu máy chịu lực cao, hệ thống cửa gió lớn cho sức gió thổi mạnh mẽ và bền bỉ.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giảng đường, trường học, cửa hàng tiện lợi, không gian trần thô phong cách tối giản.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế dạng khối đặt sàn vững chãi, lưu lượng gió thổi cực đại giúp hạ nhiệt độ không gian rộng lớn chỉ trong vài phút.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng lớn, showroom ô tô, nhà xưởng, sảnh đón khách đông người.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Cốt Lõi Làm Nên Tên Tuổi Của Carrier", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sự vượt trội giúp máy lạnh Carrier duy trì vị thế hàng đầu trong ngành công nghiệp điều hòa nằm ở các nền tảng công nghệ bền bỉ và tối ưu năng lượng:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Động cơ Hybrid Inverter tiết kiệm điện năng vượt trội", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống Hybrid Inverter của Carrier tích hợp hai mô-đun điều khiển thông minh độc lập: PAM (hoạt động với công suất tối đa để làm lạnh căn phòng nhanh nhất ngay khi khởi động) và PWM (duy trì nhiệt độ phòng ổn định ở tần số thấp để tối ưu hóa lượng điện tiêu thụ). Sự kết hợp này giúp tiết kiệm điện năng lên đến 50% so với các dòng máy cơ thông thường.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Công nghệ làm lạnh nhanh Hi-Power", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khi kích hoạt chế độ Hi-Power trên remote, máy lạnh Carrier sẽ tự động giảm nhiệt độ cài đặt xuống thêm 3 độ C, đồng thời đẩy tốc độ quạt gió lên mức tối đa. Luồng gió lạnh mạnh mẽ sẽ nhanh chóng bao phủ toàn bộ không gian, giúp căn phòng mát lạnh ngay lập tức mà không cần chờ đợi lâu.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Hệ thống lọc khí tinh khiết Nano Silver và Nhân sâm", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Carrier bảo vệ sức khỏe người dùng bằng việc trang bị bộ lọc tiên tiến kết hợp giữa các phân tử Bạc (Nano Silver) và chiết xuất nhân sâm tự nhiên. Hệ thống này có khả năng kháng khuẩn cực mạnh, tiêu hủy tế bào vi khuẩn, vi-rút bám trên bề mặt màng lọc, loại bỏ các tác nhân gây dị ứng và khử sạch các mùi hôi khó chịu trong không khí.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Công nghệ chống bám bẩn và Tự làm sạch Clean Shell", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Các lá nhôm tản nhiệt của dàn lạnh được phủ một lớp bảo vệ cao cấp ngăn ngừa bụi bẩn, dầu mỡ và nấm mốc bám dính. Sau khi tắt máy, quạt gió sẽ tiếp tục chạy thông minh trong vòng 20 phút để sấy khô toàn bộ dàn lạnh, cuốn trôi hơi ẩm dư thừa ra ngoài, ngăn chặn tận gốc sự phát triển của ẩm mốc.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Carrier Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lựa chọn đúng công suất giúp máy vận hành đúng hiệu năng, bảo vệ máy nén không bị chạy quá tải và kéo dài tuổi thọ thiết bị:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng học nhỏ, phòng làm việc cá nhân).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách căn hộ nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách lớn, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, showroom trưng bày, cửa hàng kinh doanh).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành riêng cho các dòng máy thương mại công suất lớn (Âm trần, giấu trần, tủ đứng) lắp đặt cho các không gian rộng lớn ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'carrier';
UPDATE brands SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Thương Hiệu ACIS: Giải Pháp Nhà Thông Minh Đột Phá Bằng Công Nghệ Việt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ACIS (thành lập từ năm 2012) là một trong những thương hiệu tiên phong và dẫn đầu trong lĩnh vực nghiên cứu, sản xuất các giải pháp nhà thông minh (Smarthome) trọn gói tại Việt Nam. Định vị ở phân khúc cao cấp nhưng mang tính thực tiễn vượt trội, ACIS sở hữu năng lực tự chủ hoàn toàn 100% từ khâu thiết kế phần cứng, viết phần mềm đến sản xuất thiết bị. Thương hiệu này khẳng định vị thế nhờ công nghệ kết nối không dây Mesh Network độc quyền, mở ra giải pháp thi công đột phá: biến nhà thông thường thành nhà thông minh một cách dễ dàng mà hoàn toàn không cần đục phá tường hay thay đổi cấu trúc điện.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Danh Mục Thiết Bị Cốt Lõi Trong Hệ Sinh Thái ACIS", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ sinh thái sản phẩm của ACIS cung cấp đầy đủ các mắt xích để điều khiển, giám sát và tự động hóa toàn diện ngôi nhà:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Bảng Điều Khiển Cảm Ứng Thông Minh (Smart Switch)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Đây là dòng sản phẩm mặt công tắc cảm ứng cao cấp thay thế hoàn toàn công tắc cơ truyền thống, mang lại vẻ đẹp sang trọng tuyệt đối cho mặt tường.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dòng Luxury Series:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thiết kế viền nhôm nguyên khối cắt kim cương (CNC) tinh tế, kết hợp mặt kính cường lực đen hoặc trắng. Phù hợp cho biệt thự, penthouse và chung cư hạng sang.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dòng Elegance Series:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thiết kế tràn viền tinh giản, hiện đại và thanh lịch. Phù hợp cho nhà phố, chung cư cao cấp và các văn phòng hiện đại.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bảng điều khiển ngữ cảnh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Cho phép lập trình tích hợp hàng loạt lệnh bật/tắt thiết bị điện cùng lúc chỉ bằng một nút chạm duy nhất (ví dụ: nút \\"Đi ngủ\\", \\"Tiệc tùng\\", \\"Ra ngoài\\").", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Cảm Biến Thông Minh (Smart Sensor)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Linh hồn tạo nên tính năng \\"tự động hóa\\" giúp ngôi nhà tự nhận biết và phục vụ đời sống con người mà không cần thao tác thủ công.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cảm biến chuyển động & hiện diện:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tự động kích hoạt bật đèn hành lang, cầu thang, nhà vệ sinh khi có người bước vào và tắt khi họ đi ra, giúp tối ưu hóa tiền điện.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cảm biến cửa:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giám sát trạng thái đóng/mở của hệ thống cửa, lập tức gửi cảnh báo an ninh về điện thoại nếu phát hiện có sự xâm nhập trái phép vào ban đêm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cảm biến môi trường:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đo đạc nhiệt độ, độ ẩm để tự động ra lệnh điều chỉnh máy điều hòa hoặc bật máy hút ẩm khi thời tiết thay đổi.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Thiết Bị Điều Khiển Bỏ Túi & Trung Tâm", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Remote cầm tay thông minh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thiết bị điều khiển ngữ cảnh bỏ túi nhỏ gọn, cực kỳ thân thiện với người già và trẻ nhỏ khi cần kích hoạt nhanh các kịch bản sống mà không muốn thao tác trên smartphone.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bộ điều khiển trung tâm (Master Gateway):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đầu não kết nối tất cả thiết bị trong nhà, đồng bộ dữ liệu lên đám mây để người dùng điều khiển từ xa qua ứng dụng ACIS trên điện thoại.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Điểm Cộng Độc Quyền Tạo Nên Sự Khác Biệt Của ACIS", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Để ăn điểm tuyệt đối trong mắt khách hàng và đạt thứ hạng cao trên các công cụ tìm kiếm, hệ thống ACIS sở hữu 3 điểm bán hàng độc nhất (USP):", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ không dây Mesh Network tự phục hồi:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ACIS không sử dụng sóng Wi-Fi hay Zigbee thông thường. Công nghệ sóng độc quyền của ACIS giúp các thiết bị tự làm trạm tiếp sóng cho nhau. Nhờ đó, hệ thống có khả năng xuyên tường bê tông cực tốt, sóng phủ đều từ tầng hầm lên sân thượng và phản hồi lập tức không có độ trễ.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Giải pháp \\"Retrofit\\" - Nâng cấp không đục tường:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Các bảng điều khiển và công tắc ACIS được thiết kế theo kích thước tiêu chuẩn hình chữ nhật và hình vuông, tương thích hoàn hảo với các loại đế âm tường có sẵn trên thị trường (Sino, Panasonic...). Việc thi công lắp đặt cực kỳ nhanh chóng, chỉ cần tháo công tắc cũ ra và lắp công tắc ACIS vào, giữ nguyên vẹn thẩm mỹ ngôi nhà.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Khả năng hoạt động Local khi mất Internet:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nếu mạng Internet hoặc Wi-Fi trong nhà bị sự cố, toàn bộ hệ thống kịch bản tự động hóa và các công tắc cảm ứng ACIS vẫn liên kết hoạt động bình thường qua mạng sóng nội bộ, đảm bảo sinh hoạt gia đình không bị gián đoạn.", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'acis';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Hagisu: Thương Hiệu Công Nghệ Mới Cho Mọi Không Gian Sống", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy lạnh Hagisu là dòng sản phẩm điều hòa không khí thế hệ mới đang ngày càng khẳng định vị thế trên thị trường nhờ sự kết hợp hoàn hảo giữa công nghệ làm lạnh tiên tiến, khả năng tiết kiệm điện vượt trội và thiết kế hiện đại. Với dải sản phẩm đa dạng từ máy lạnh treo tường dân dụng đến các dòng máy lạnh thương mại công suất lớn, Hagisu mang đến giải pháp làm mát toàn diện, tối ưu chi phí đầu tư và vận hành cho cả hộ gia đình lẫn doanh nghiệp.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Hagisu Nổi Bật Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hagisu cung cấp đầy đủ các giải pháp làm mát nhằm đáp ứng trọn vẹn mọi yêu cầu thiết kế kiến trúc và diện tích không gian:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Thiết Kế & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường Hagisu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế nhỏ gọn, kiểu dáng thanh lịch thời trang, mặt nạ phẳng dễ vệ sinh. Vận hành êm ái.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ, phòng khách nhỏ, căn hộ chung cư, phòng làm việc cá nhân.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Hagisu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Toàn bộ thân máy giấu trong trần, mặt nạ đa hướng thổi giúp phân bổ hơi lạnh đều khắp phòng mà không gây buốt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán cafe, nhà hàng, văn phòng làm việc, showroom, sảnh tiệc.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần Hagisu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp áp sát vào trần bê tông, sức gió thổi cực mạnh và xa, không tốn không gian hạ trần thạch cao.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lớp học, giảng đường, cửa hàng tiện lợi, không gian phong cách Industrial.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng Hagisu", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dạng tủ đặt sàn cơ động, tốc độ làm lạnh nhanh vô địch ngay khi vừa khởi động nhờ lưu lượng gió lớn.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng, showroom lớn, nhà xưởng, không gian có khách ra vào liên tục.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Cốt Lõi Trên Máy Lạnh Hagisu", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Để đáp ứng tiêu chuẩn khắt khe của người tiêu dùng hiện đại, Hagisu tích hợp hàng loạt công nghệ thông minh nhằm nâng cao trải nghiệm sử dụng:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ biến tần Inverter thông minh", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống máy nén Inverter của Hagisu có khả năng tự động điều chỉnh tần số hoạt động để duy trì nhiệt độ cài đặt một cách chính xác nhất. Công nghệ này giúp máy vận hành siêu êm ái, giảm thiểu ma sát, kéo dài tuổi thọ động cơ và tiết kiệm từ 30% đến 50% điện năng tiêu thụ so với các dòng máy cơ thông thường.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Chế độ làm lạnh siêu tốc Turbo", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khi kích hoạt chế độ Turbo trên điều khiển, máy lạnh Hagisu sẽ lập tức đẩy công suất hoạt động của máy nén và tốc độ quạt gió lên mức tối đa. Không gian phòng sẽ được làm mát toàn diện chỉ trong vòng 3 đến 5 phút, giải tỏa ngay lập tức cái nóng oi bức.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Hệ thống lọc khí đa tầng sạch khuẩn", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bên cạnh khả năng làm mát, Hagisu đặc biệt chú trọng đến sức khỏe người dùng bằng việc trang bị các lớp màng lọc mật độ cao. Hệ thống này giúp giữ lại các hạt bụi mịn, loại bỏ các tác nhân gây dị ứng, nấm mốc và khử mùi hôi khó chịu trong không khí, trả lại không gian sống trong lành.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Sử dụng môi chất lạnh R32 thân thiện môi trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tất cả các dòng máy lạnh đời mới của Hagisu đều sử dụng gas R32. Đây là loại môi chất lạnh thế hệ mới nhất, không chỉ mang lại hiệu suất làm lạnh sâu hơn, tiết kiệm năng lượng hơn mà còn an toàn cho sức khỏe và giảm thiểu tối đa chỉ số gây hiệu ứng nhà kính.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Hagisu Phù Hợp Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Việc tính toán đúng công suất giúp máy hoạt động bền bỉ, tránh tình trạng quá tải gây tốn điện hoặc lãng phí hiệu năng:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho phòng có diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng đọc sách).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng làm việc chung).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách căn hộ, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, cửa hàng, không gian mở liền kề bếp).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Từ 36.000 Btu/h đến 100.000 Btu/h:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành riêng cho các không gian thương mại và công nghiệp diện tích lớn ", "type": "text"}, {"text": "từ 45m2 trở lên", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'hagisu';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Mitsubishi: Đỉnh Cao Bền Bỉ Và Công Nghệ Làm Lạnh Chuẩn Công Nghiệp", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Máy lạnh Mitsubishi (bao gồm hai dòng thương hiệu uy tín là Mitsubishi Heavy Industries và Mitsubishi Electric) từ lâu đã khẳng định vị thế vững chắc tại thị trường Việt Nam nhờ triết lý sản xuất bền bỉ, nồi đồng cối đá và khả năng làm lạnh cực kỳ sâu. Được phát triển dựa trên nền tảng kỹ thuật công nghiệp nặng, hệ thống điều hòa Mitsubishi sở hữu hiệu suất vận hành mạnh mẽ, tuổi thọ thiết bị vượt trội và dải công sản phẩm toàn diện đáp ứng mọi loại hình kiến trúc.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Mitsubishi Phổ Biến Trên Thị Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Mitsubishi cung cấp hệ thống giải pháp làm mát đa dạng, từ dân dụng đến các hệ thống thương mại công suất lớn:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Mitsubishi", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế góc cạnh, chắc chắn. Khả năng làm lạnh sâu và nhanh, máy nén vận hành cực kỳ êm và bền bỉ theo thời gian.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ gia đình, phòng khách nhỏ, chung cư, văn phòng cá nhân.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống mặt nạ đa hướng thổi giúp tản hơi lạnh đều, tích hợp bơm nước ngưng mạnh mẽ và thiết kế dễ lắp đặt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán cafe, nhà hàng kinh doanh, văn phòng làm việc, showroom.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng máy áp suất tĩnh cao (High Static Pressure) đỉnh cao, thổi gió siêu xa thông qua hệ thống ống gió giấu trần sang trọng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự, Penthouse, trung tâm hội nghị, căn hộ cao cấp lớn.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp sát trần bê tông, kiểu dáng gọn gàng, động cơ mạnh mẽ chịu được tần suất hoạt động liên tục.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giảng đường, trường học, cửa hàng tiện lợi, không gian trần thô.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Công suất lớn, thiết kế khối vững chắc đặt sàn, lưu lượng gió cực đại thổi trực tiếp làm mát không gian rộng trong vài phút.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng lớn, nhà xưởng sản xuất, sảnh tiệc, hội trường.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Cốt Lõi Tạo Nên Uy Tín Của Mitsubishi", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sức mạnh cạnh tranh giúp Mitsubishi luôn đứng top đầu phân khúc máy lạnh cao cấp nằm ở các nền tảng công nghệ cơ khí và điều khiển thông minh:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ Jet Engine (Mô phỏng động cơ phản lực)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Áp dụng công nghệ tính toán động lực học chất lưu (CFD) từ việc thiết kế cánh máy bay phản lực vào hệ thống cánh quạt của máy lạnh. Công nghệ Jet Flow giúp sản sinh ra lưu lượng gió cực lớn nhưng tiêu thụ điện năng tối thiểu, luồng gió có thể thổi xa lên đến 15 - 17 mét, phân bổ hơi lạnh đều khắp các góc phòng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Công nghệ PAM Inverter tiết kiệm điện tối đa", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống biến tần PAM Inverter của Mitsubishi có khả năng điều khiển sóng dòng điện sao cho trùng khớp với sóng điện thế nguồn. Cơ chế này giúp thiết bị sử dụng hiệu quả lên đến 98% nguồn điện đầu vào, tránh thất thoát năng lượng, tăng tốc độ làm lạnh nhanh và tối ưu hóa hóa đơn tiền điện hằng tháng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Mắt thần cảm biến thông minh (3D I-See Sensor)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Cảm biến liên tục quét không gian phòng 360 độ để phát hiện vị trí của con người dựa trên nhiệt độ cơ thể. Hệ thống sẽ tự động điều chỉnh hướng gió thổi trực tiếp hoặc thổi gián tiếp né người tùy theo cài đặt, đồng thời tự giảm công suất khi phòng không có ai để tiết kiệm điện.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Lớp phủ kép chống bám bẩn độc quyền", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dàn lạnh được phủ một lớp bảo vệ kép đặc biệt, ngăn ngừa tích tụ bụi bẩn, khói thuốc và dầu mỡ bám vào cánh quạt, cánh đảo gió hay các linh kiện bên trong. Công nghệ này giúp luồng khí thổi ra luôn sạch sẽ, duy trì hiệu suất làm lạnh ổn định lâu dài và giảm số lần phải gọi thợ vệ sinh máy.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Mitsubishi Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lựa chọn đúng công suất giúp máy vận hành đúng hiệu năng, bảo vệ block máy nén không bị quá tải:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ, phòng đọc sách nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng làm việc riêng).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách căn hộ, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán kinh doanh, showroom, phòng khách lớn liền bếp).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành cho các dòng máy thương mại công suất lớn lắp đặt cho diện tích ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'mitsubishi';
UPDATE brands SET content = E'{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Panasonic: Đỉnh Cao Công Nghệ Thanh Lọc Không Khí Và Tiết Kiệm Điện Smart AI", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Panasonic là thương hiệu điện tử, điện lạnh cao cấp hàng đầu thế giới đến từ Nhật Bản. Với hơn 100 năm phát triển, dòng sản phẩm máy lạnh Panasonic luôn khẳng định vị thế dẫn đầu thị trường nhờ sự kết hợp hoàn hảo giữa kiểu dáng thiết kế sang trọng, độ bền bỉ vượt trội và đặc biệt là hệ thống lọc khí bảo vệ sức khỏe toàn diện. Đây là lựa chọn hàng đầu cho các không gian sống hiện đại, đòi hỏi khắt khe về chất lượng không khí.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Panasonic Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Panasonic sở hữu dải sản phẩm điều hòa không khí đa dạng, đáp ứng trọn vẹn mọi yêu cầu thiết kế và quy mô công trình:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Panasonic", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế thanh lịch, tinh tế. Sở hữu các dòng Inverter cao cấp (XU, VU) tích hợp công nghệ lọc khí Nanoe-X hoạt động độc lập.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ, phòng khách nhỏ, căn hộ chung cư cao cấp, phòng làm việc riêng.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế mặt nạ 4 hướng thổi rộng phẳng, hướng gió thổi xa và đều, tích hợp sẵn công nghệ lọc khí Nanoe-X thế hệ mới.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nhà hàng, quán cafe, văn phòng làm việc đông người, showroom thời trang.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kích thước dàn lạnh siêu mỏng nhẹ, dễ dàng lắp đặt trong các hộp trần hẹp, mang lại tính thẩm mỹ độc bản tối giản.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự, Penthouse, căn hộ chung cư hạng sang, phòng khách lớn.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế mỏng ôm sát bề mặt trần bê tông, cửa gió lớn phân phối lưu lượng khí mát mạnh mẽ và đồng đều.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giảng đường, trường học, cửa hàng tiện lợi, không gian trần thô.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế dạng tủ đứng đặt sàn thời trang, công suất lớn, tốc độ làm mát diện tích rộng tức thì ngay khi khởi động.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách lớn thông tầng, biệt thự rộng, nhà xưởng, sảnh đón khách.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Đột Phá Làm Nên Thương Hiệu Panasonic", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sự vượt trội giúp Panasonic giữ vững phân khúc cao cấp nằm ở các công nghệ độc quyền hướng tới sức khỏe và sự tiện nghi tối đa:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ thanh lọc không khí độc quyền Nanoe-X", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Đây là công nghệ \\"đáng tiền\\" nhất của Panasonic. Hệ thống phát ra các gốc hydroxyl (OH) tự do bọc trong nước để chủ động ức chế 99.99% sự phát triển của vi khuẩn, virus (kể cả các chủng virus bám dính), nấm mốc, phấn hoa và khử các mùi hôi khó chịu (khói thuốc, mùi thức ăn). Đặc biệt, hệ thống Nanoe-X có thể hoạt động độc lập như một chiếc máy lọc không khí chuyên dụng ngay cả khi không bật chế độ làm lạnh.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Công nghệ lọc bụi mịn PM2.5 với Nanoe-G", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống giải phóng hàng tỷ ion âm vào không khí để liên kết với các hạt bụi siêu mịn (kể cả bụi mịn PM2.5). Sau đó, các hạt bụi mang điện tích âm này sẽ bị hút ngược lại và giữ chặt tại màng lọc của máy, trả lại bầu không khí trong lành cho căn phòng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Công nghệ biến tần Inverter kết hợp Chế độ ECO tích hợp A.I", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sự kết hợp giữa động cơ biến tần Inverter và trí tuệ nhân tạo (A.I) giúp máy lạnh Panasonic tự động nhận biết nhiệt độ môi trường và số lượng người trong phòng để điều chỉnh công suất làm lạnh tối ưu. Máy có khả năng tiết kiệm điện năng tiêu thụ lên đến 20% so với chế độ Inverter thông thường mà vẫn đảm bảo sự thoải mái.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Thiết kế cánh đảo gió kép Aerowings và iAUTO-X", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "iAUTO-X:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng công nghệ kiểm soát nhiệt độ thông minh giúp máy làm lạnh nhanh hơn 35% ngay khi vừa khởi động.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Aerowings:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Trang bị hai cánh đảo gió độc lập giúp hướng luồng gió thổi xa và tập trung hơn để làm mát nhanh, sau đó hướng luồng gió lên trần nhà (luồng gió dễ chịu) để tránh thổi trực tiếp vào người gây buốt.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Panasonic Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tính toán đúng công suất dựa trên diện tích phòng giúp hệ thống máy lạnh vận hành ổn định, tiết kiệm điện và kéo dài tuổi thọ:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho phòng có diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng học nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách căn hộ nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách lớn, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, showroom, cửa hàng kinh doanh).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 34.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành riêng cho các dòng máy thương mại (Âm trần, giấu trần, tủ đứng) lắp đặt cho không gian rộng lớn ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'panasonic';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh Midea: Giải Pháp Làm Lạnh Giá Rẻ, Hiệu Quả Và Tiết Kiệm Tối Ưu", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Midea là một trong những tập đoàn sản xuất thiết bị điện lạnh, điện gia dụng lớn nhất thế giới có trụ sở tại Trung Quốc và sở hữu nhiều nhà máy sản xuất hiện đại tại Việt Nam. Tại thị trường trong nước, máy lạnh Midea luôn giữ vững vị thế là dòng máy quốc dân ở phân khúc giá rẻ nhờ giá thành cực kỳ cạnh tranh, chi phí linh kiện thay thế rẻ, khả năng làm lạnh nhanh chóng và thiết kế ngày càng cải tiến hiện đại, phù hợp với ngân sách của đại đa số người tiêu dùng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh Midea Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Midea đáp ứng trọn vẹn mọi phân khúc lắp đặt từ các hộ gia đình nhỏ đến các không gian kinh doanh thương mại với dải sản phẩm đầy đủ:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm Midea", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giá thành siêu rẻ, thiết kế bo cong thanh lịch. Nổi bật với các dòng Xtreme Save tiết kiệm điện hoặc dòng máy cơ làm lạnh tức thì.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ gia đình, phòng trọ, căn hộ cho thuê, văn phòng nhỏ.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế mặt nạ 4 hướng thổi gió rộng, tích hợp sẵn bơm nước ngưng, thi công lắp đặt nhanh chóng và giá đầu tư cực tốt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán cafe, shop thời trang, nhà hàng ăn uống, văn phòng làm việc.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Giải pháp giấu trần thẩm mỹ với chi phí vật tư và máy rẻ hơn nhiều so với các hãng cao cấp, dải áp suất tĩnh linh hoạt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Căn hộ chung cư, nhà phố hiện đại, nhà hàng tiệc cưới.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lắp sát trần bê tông, kết cấu máy chắc chắn, quạt gió công suất lớn giúp thổi luồng khí mát đi xa và rộng.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trường học, giảng đường, cửa hàng tiện lợi, kho bãi, xưởng nhỏ.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế dạng cây đặt sàn vững chãi, lưu lượng gió thổi mạnh mẽ trực diện, làm mát toàn bộ phòng rộng trong thời gian ngắn.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng, sảnh đón khách, showroom, hội trường đông người.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Cốt Lõi Trên Máy Lạnh Midea", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dù nằm ở phân khúc bình dân, Midea vẫn được trang bị những công nghệ tiên tiến nhằm tối ưu hóa trải nghiệm làm mát và tiết kiệm chi phí cho người dùng:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ biến tần Inverter Quattro và Chế độ Xtreme Save", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống Inverter Quattro thế hệ mới của Midea cho phép máy nén quay với tốc độ cực cao ngay khi khởi động để làm lạnh nhanh, sau đó duy trì tần số thấp ổn định để tiết kiệm năng lượng. Kết hợp với thuật toán điều khiển chính xác Xtreme Save, máy có thể kiểm soát lượng điện tiêu thụ một cách hiệu quả, giảm thiểu chi phí tiền điện hằng tháng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Chế độ làm lạnh nhanh Boost / Turbo", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khi kích hoạt chế độ làm lạnh nhanh trên remote, máy nén và quạt gió sẽ hoạt động với công suất tối đa để hạ nhiệt độ phòng xuống mức cài đặt chỉ trong vòng vài phút. Người dùng sẽ lập tức cảm nhận được luồng khí mát lạnh sảng khoái mà không cần mất thời gian chờ đợi.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Công nghệ lọc bụi kép Dual Filtration", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Midea trang bị hệ thống lọc hai lớp bao gồm màng lọc thô có mật độ cao giúp giữ lại các hạt bụi lớn, xơ vải, lông thú cưng và màng lọc tăng cường giúp khử các mùi hôi khó chịu như mùi thuốc lá, mùi thức ăn. Bộ lọc này giúp giữ cho không khí trong phòng luôn thoáng đãng, bảo vệ hệ hô hấp cơ bản.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Công nghệ tự động làm sạch dàn lạnh Self-Cleaning", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sau khi tắt máy lạnh, quạt gió bên trong dàn lạnh vẫn sẽ tiếp tục quay ở chế độ nhiệt độ thấp để sấy khô toàn bộ các lá nhôm tản nhiệt. Quá trình này giúp loại bỏ hoàn toàn nước đọng dư thừa, ngăn chặn tận gốc sự hình thành và phát triển của nấm mốc, vi khuẩn bám trên dàn, giữ cho luồng khí luôn sạch mùi.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh Midea Theo Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lựa chọn công suất máy lạnh phù hợp giúp hệ thống vận hành ổn định, tăng tuổi thọ thiết bị và tránh lãng phí điện năng:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ nhỏ, phòng trọ, phòng làm việc cá nhân).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách căn hộ, phòng họp nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe nhỏ, cửa hàng, văn phòng chung).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành cho các dòng máy thương mại (Âm trần, tủ đứng) lắp đặt ở không gian rộng lớn ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'midea';
UPDATE brands SET content = '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Máy Lạnh LG: Đỉnh Cao Công Nghệ Hiện Đại Và Giải Pháp Tiết Kiệm Điện Vượt Trội", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "LG là thương hiệu điện tử, điện lạnh toàn cầu đến từ Hàn Quốc, luôn tiên phong trong việc mang các công nghệ thông minh, tiện ích hiện đại vào không gian sống. Tại Việt Nam, máy lạnh LG cực kỳ được ưa chuộng nhờ kiểu dáng thiết kế sang trọng, tinh tế, tích hợp nhiều tính năng bảo vệ sức khỏe cao cấp và đặc biệt là khả năng vận hành thông minh giúp tối ưu hóa chi phí điện năng hằng tháng cho người dùng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các Dòng Sản Phẩm Máy Lạnh LG Phổ Biến Trên Thị Trường", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "LG cung cấp dải sản phẩm điều hòa không khí toàn diện, đáp ứng hoàn hảo từ nhu cầu dân dụng đến các công trình thương mại phức tạp:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dòng Sản Phẩm LG", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Đặc Điểm Kỹ Thuật & Vận Hành", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Không Gian Lắp Đặt Phù Hợp", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh treo tường", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kiểu dáng mỏng nhẹ, sang trọng. Sở hữu các dòng Dual Inverter phổ thông đến các dòng tích hợp thanh lọc không khí cao cấp.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng ngủ, căn hộ chung cư, phòng làm việc cá nhân, phòng khách nhỏ.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh âm trần Cassette", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế đa hướng thổi độc lập (4 cánh đảo gió chỉnh riêng biệt), tích hợp sẵn bơm nước ngưng và mặt nạ thanh lọc bụi mịn.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Quán kinh doanh cafe, nhà hàng, showroom thời trang, văn phòng công ty.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh giấu trần nối ống gió", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thân máy siêu mỏng dễ lắp đặt trong trần hẹp, hơi lạnh dẫn qua hệ thống ống gió mang lại tính thẩm mỹ tuyệt đối.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Biệt thự cao cấp, Penthouse, chung cư hạng sang, phòng khách lớn.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh áp trần", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế hiện đại đoạt giải thưởng quốc tế, ôm sát trần bê tông, sức gió thổi mạnh mẽ và tản nhiệt cực tốt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trường học, giảng đường, cửa hàng tiện lợi, không gian trần thô.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh tủ đứng", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thiết kế Slim (siêu mỏng) tinh tế như một món đồ decor, khả năng thổi gió xa lên đến 20 mét làm mát tức thì.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phòng khách thông tầng biệt thự, showroom lớn, nhà xưởng, hội trường.", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những Công Nghệ Cốt Lõi Tạo Nên Khác Biệt Của LG", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Để chinh phục người tiêu dùng hiện đại, LG trang bị hàng loạt công nghệ đột phá hướng tới sự tiện nghi, an toàn và tiết kiệm:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. Công nghệ máy nén biến tần Dual Inverter", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khác với máy nén biến tần thông thường, công nghệ Dual Inverter của LG sử dụng mô-tơ kép với dải tần số hoạt động rộng hơn. Nhờ đó, máy có khả năng làm lạnh nhanh hơn đến 40%, giảm rung lắc tối đa giúp máy vận hành êm ái, đồng thời cắt giảm chi phí hóa đơn tiền điện lên đến 70% so với dòng máy cơ.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. Hệ thống thanh lọc không khí và Diệt khuẩn UVnano", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Màng lọc bụi mịn PM1.0:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tích hợp bộ cảm biến bụi thông minh, tự động phát hiện và lọc sạch các hạt bụi siêu mịn, bảo vệ hệ hô hấp toàn diện.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ UVnano:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng đèn LED tia cực tím được tích hợp bên trong dàn lạnh để loại bỏ 99.99% vi khuẩn, virus bám trên cánh quạt gió, đảm bảo luồng khí thổi ra luôn tinh khiết, sạch khuẩn.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. Công nghệ kiểm soát năng lượng chủ động (Energy Control)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "LG cho phép người dùng tự chủ động điều chỉnh mức công suất tiêu thụ điện của máy lạnh theo 4 mức (100%, 80%, 60% và 40%) tùy thuộc vào số lượng người trong phòng và thời tiết. Tính năng này giúp tối ưu hóa lượng điện tiêu thụ một cách linh hoạt nhất.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "4. Kết nối thông minh qua Wi-Fi và Ứng dụng LG ThinQ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tất cả các dòng máy lạnh thông minh của LG đều hỗ trợ kết nối Wi-Fi. Người dùng có thể dễ dàng bật/tắt máy, điều chỉnh nhiệt độ, hẹn giờ, theo dõi lượng điện tiêu thụ hoặc chẩn đoán lỗi thông minh của máy ở bất cứ đâu thông qua ứng dụng LG ThinQ trên điện thoại.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hướng Dẫn Chọn Công Suất Máy Lạnh LG Phù Hợp Diện Tích", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Việc tính toán đúng công suất dựa trên diện tích phòng giúp máy hoạt động hiệu quả, bền bỉ và tiết kiệm năng lượng tối đa:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "9.000 Btu/h (1 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho phòng có diện tích ", "type": "text"}, {"text": "dưới 15m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ gia đình, phòng đọc sách).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "12.000 Btu/h (1.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "15m2 - 20m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng ngủ lớn, phòng khách nhỏ).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "18.000 Btu/h (2 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "20m2 - 30m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Phòng khách căn hộ, phòng họp công ty).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "24.000 Btu/h (2.5 HP):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho diện tích từ ", "type": "text"}, {"text": "30m2 - 40m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Quán cafe, showroom trưng bày, cửa hàng).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công suất từ 36.000 Btu/h trở lên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dành cho các dòng máy thương mại (Âm trần, giấu trần, tủ đứng) phục vụ không gian rộng lớn ", "type": "text"}, {"text": "trên 45m2", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph"}]}'::jsonb WHERE slug = 'lg';
